import React, { useState, useEffect, useCallback } from "react";
import { MdKeyboardArrowLeft, MdArrowForward } from "react-icons/md";

import Fade from "../animations/fade";
import Loading from "./loading";
import Button from "./button";
import Input from "./input";
import KioskCard from "./kiosk-card";
import { getConfig, getKiosks } from "../utils/service-api";
import {
  addListener,
  removeListener,
  sendMessage
} from "../utils/window-messaging";
import styles from "./login.module.css";

/**
 * Overview of the login process:
 *  - user enters an ID number
 *  - download and present a list of kiosks
 *  - user will pick a kiosk; ask for confirmation
 *  - download config for that kiosk
 */
export default function Login({ isOpen = true, isIdle, onLogin }) {
  let [passcode, setPasscode] = useState("");
  let [kiosks, setKiosks] = useState(null);
  let [selectedKiosk, setSelectedKiosk] = useState(null);
  let [config, setConfig] = useState(null);

  let [isLoading, setIsLoading] = useState(true);
  let [errorMessage, setErrorMessage] = useState("");
  let [isDownloading, setIsDownloading] = useState(null);
  let [downloadMessage, setDownloadMessage] = useState("");

  usePreviousConfig(setConfig, setIsLoading, setIsDownloading);

  const resetInputs = () => {
    setConfig(null);
    setSelectedKiosk(null);
    setKiosks(null);
    setPasscode("");
  };

  const handleCodeChange = e => {
    setErrorMessage("");
    let code = e.target.value;
    // accept alphanumeric and "-"
    code = code.replace(/[^a-zA-Z0-9-]/g, "");
    code = code.slice(0, 15);
    setPasscode(code);
  };

  const handleCodeSubmit = () => {
    setIsLoading(true);
    setErrorMessage("");
    getKiosks(passcode)
      .then(kiosks => {
        // filter out the 'template' kiosk and sort by kiosk number
        setIsLoading(false);
        kiosks = kiosks
          .filter(k => k.number && k.location)
          .sort((k1, k2) => k1.number - k2.number);
        setKiosks(kiosks);
      })
      .catch(error => {
        resetInputs();
        setIsLoading(false);
        setErrorMessage(error);
      });
  };

  const confirmSelection = useCallback(() => {
    setIsLoading(true);
    getConfig(selectedKiosk.id, selectedKiosk.dealerName)
      .then(config => {
        setConfig(config);
        setIsDownloading(true);
      })
      .catch(err => {
        resetInputs();
        setIsLoading(false);
        setErrorMessage(err);
      });
  }, [selectedKiosk]);

  // Select the kiosk automatically if there is only one available.
  useEffect(() => {
    const singleKiosk = kiosks && kiosks.length === 1;
    if (!singleKiosk) return;

    if (!selectedKiosk) {
      setSelectedKiosk(kiosks[0]);
    } else {
      confirmSelection(kiosks[0]);
    }
  }, [kiosks, selectedKiosk, confirmSelection]);

  const handleDownloadComplete = useCallback(
    async config => {
      window.localStorage.setItem("config", btoa(JSON.stringify(config)));
      setIsDownloading(false);
      setDownloadMessage("Applying styles...");
      await applyFonts(config.data.fonts);
      applyStyles(config.data.styles);

      onLogin(config);
    },
    [setIsDownloading, setDownloadMessage, onLogin]
  );

  const handleTrialLogin = useCallback(() => {
    if (!window.isNative) return;

    setIsLoading(true);
    const trialConfig = require("../native/trial-config.json");
    handleDownloadComplete(trialConfig);
  }, [handleDownloadComplete]);

  const handleDownloadError = useCallback(
    error => {
      window.localStorage.removeItem("config");
      resetInputs();
      setIsDownloading(null);
      setDownloadMessage("");
      setIsLoading(false);
      setErrorMessage(error);
    },
    [setIsDownloading, setDownloadMessage, setIsLoading, setErrorMessage]
  );

  useDownload(
    config,
    isDownloading,
    setDownloadMessage,
    handleDownloadComplete,
    handleDownloadError
  );

  useConfigUpdates(config, isIdle);

  return (
    <Fade className={styles.overlay} in={isOpen} duration={1000}>
      {isLoading && <Loading text={downloadMessage} />}

      {!isLoading && !kiosks && (
        <div className={styles.content}>
          <h1 className={styles.prompt}>
            Enter your customer number to download a catalog customized for you.
          </h1>

          <div className={styles.input}>
            <Input
              placeholder="Customer #"
              buttonIcon={<MdArrowForward className={styles.icon} />}
              value={passcode}
              onChange={handleCodeChange}
              onSubmit={handleCodeSubmit}
              type="password"
              shouldFocusOnRender
            />
          </div>

          <div className={styles["error-message"]}>{errorMessage}</div>

          {window.isNative && (
            <Button
              style={{ margin: "1em" }}
              onClick={() => handleTrialLogin()}
            >
              Try a trial catalog.
            </Button>
          )}

          <div className={styles.prompt}>
            If you do not have a customer number and would like to browse our
            catalog, please call 1-800-845-8877.
          </div>
        </div>
      )}

      {!isLoading && kiosks && !selectedKiosk && (
        <div className={styles.content}>
          <h1 className={styles.prompt}>Select a kiosk:</h1>

          <div className={styles.kiosks}>
            {kiosks.map((kiosk, i) => (
              <KioskCard
                key={i}
                style={i !== 0 ? { marginTop: "1em" } : null}
                kiosk={kiosk}
                onClick={() => setSelectedKiosk(kiosk)}
              />
            ))}
          </div>

          <Button alt style={{ marginTop: "1em" }} onClick={resetInputs}>
            <MdKeyboardArrowLeft className={styles.icon} />
            Enter a different customer number
          </Button>
        </div>
      )}

      {!isLoading && kiosks && selectedKiosk && (
        <div className={styles.content}>
          <h1 className={styles.prompt}>Continue with this information?</h1>

          <KioskCard style={{ width: "auto" }} kiosk={selectedKiosk} />

          <div className={styles.yesno}>
            <Button onClick={confirmSelection}>Yes, finish setup</Button>
            <Button alt onClick={() => setSelectedKiosk(null)}>
              No, select another
            </Button>
          </div>
        </div>
      )}
    </Fade>
  );
}

function usePreviousConfig(setConfig, setIsLoading, setIsDownloading) {
  useEffect(() => {
    // bypass kiosk selection process if it's been done before
    let previousConfig = window.localStorage.getItem("config");

    if (previousConfig) {
      previousConfig = JSON.parse(atob(previousConfig));
      if (previousConfig && previousConfig.auth && previousConfig.data) {
        if (previousConfig.data.products.url === "trial-products.json") {
          // trial account, don't use this login
          window.localStorage.removeItem("config");
          setIsLoading(false);
          return;
        }

        let [id, dealerName] = atob(previousConfig.auth).split(":");
        // attempt to fetch new configuration
        getConfig(id, dealerName)
          .then(newConfig => {
            setConfig(newConfig);
            setIsDownloading(true);
          })
          .catch(() => {
            setConfig(previousConfig);
            setIsDownloading(true);
          });
      }
    } else {
      setIsLoading(false);
    }
  }, [setConfig, setIsLoading, setIsDownloading]);
}

function useDownload(
  config,
  isDownloading,
  setDownloadMessage,
  onComplete,
  onError
) {
  useEffect(() => {
    if (config !== null && isDownloading) {
      sendMessage("START_DOWNLOADING_CONFIG", config);

      const handleProgress = item => {
        if (window.isNative) return;

        setDownloadMessage(`Downloading ${item}...`);
      };
      addListener("DOWNLOADING_CONFIG", handleProgress);
      addListener("FINISHED_DOWNLOADING_CONFIG", onComplete);
      addListener("ERROR_DOWNLOADING_CONFIG", onError);

      return () => {
        removeListener("DOWNLOADING_CONFIG", handleProgress);
        removeListener("FINISHED_DOWNLOADING_CONFIG", onComplete);
        removeListener("ERROR_DOWNLOADING_CONFIG", onError);
      };
    }
  }, [config, isDownloading, setDownloadMessage, onComplete, onError]);
}

async function applyFonts(fonts) {
  for (const font of fonts) {
    let { name, path, style, weight } = font;
    path = path.replace(/\\/g, m => "\\\\");
    let fontFace = new FontFace(name, `url(${path})`, { style, weight });
    document.fonts.add(fontFace);
  }
  await document.fonts.ready;
}

function applyStyles(styles) {
  let variables = [];
  for (const style in styles) {
    // convert from camelCase to --css-variable-format
    let name = "--" + style.replace(/[A-Z]/g, m => "-" + m.toLowerCase());
    variables.push({ name, value: styles[style] });
  }
  variables.forEach(variable => {
    const { name, value } = variable;
    document.documentElement.style.setProperty(name, value);
  });
}

function useConfigUpdates(config, isIdle) {
  // Only on the desktop version:
  // periodically check if there is a new config available. If there is,
  // and the kiosk is idle, refresh the page to trigger the changes.
  useEffect(() => {
    if (!window.isNative && config && isIdle) {
      const intervalMs = 60 * 60 * 1000; // 1 hour
      const timer = setInterval(() => checkConfig(config), intervalMs);

      return () => clearInterval(timer);
    }

    function checkConfig(config) {
      const [id, dealerName] = atob(config.auth).split(":");
      getConfig(id, dealerName)
        .then(newConfig => {
          if (JSON.stringify(config) !== JSON.stringify(newConfig)) {
            window.location.reload();
          } else {
            console.log("No configuration changes found.");
          }
        })
        .catch(err => {
          console.error(`Error fetching config: ${err}`);
        });
    }
  }, [config, isIdle]);
}
