import React, { useState } from "react";
import QRCode from "qrcode";
import { IoMdQrScanner } from "react-icons/io";

import Button from "./button";
import styles from "./qr-button.module.css";

export default function QrButton({ className = "", style = {}, url, prompt }) {
  let [qrCodeUri, setQrCodeUri] = useState(null);

  const createQrCodeUri = () => {
    QRCode.toString(url, { type: "svg" }).then(svgStr => {
      setQrCodeUri(`url("data:image/svg+xml;base64,${btoa(svgStr)}")`);
    });
  };

  return (
    url && (
      <div
        className={`${styles["qrcode-wrapper"]} ${
          qrCodeUri ? styles.active : ""
        } ${className}`}
        style={style}
      >
        {qrCodeUri === null ? (
          <Button
            style={{ minWidth: "10em" }}
            onClick={() => createQrCodeUri()}
          >
            <IoMdQrScanner className={styles["left-icon"]} /> QR Code
          </Button>
        ) : (
          <>
            <div className={styles.qrcode} style={{ background: qrCodeUri }} />
            {prompt && <div className={styles["qrcode-prompt"]}>{prompt}</div>}
          </>
        )}
      </div>
    )
  );
}
