import React, { useState, useContext, useEffect } from "react";

import Login from "../components/login";
import { sendMessage } from "../utils/window-messaging";
import { logEvent } from "../utils/logging";

const context = React.createContext({
  configData: null,
  isIdle: false,
  setIsIdle: () => {},
  logout: () => {}
});

export const useConfiguration = () => useContext(context);

export function ConfigurationProvider({ children }) {
  let [shouldRenderChildren, setShouldRenderChildren] = useState(false);
  let [config, setConfig] = useState(null);

  let lastInteraction = useInteractionEvents();

  let secondsUntilIdle = config ? config.data.secondsUntilIdle : 5 * 60;
  let [isIdle, setIsIdle] = useIsIdle(lastInteraction, secondsUntilIdle);

  useClearCacheOnIdle(isIdle);

  useEffect(() => {
    if (config !== null) {
      if (process.env.NODE_ENV === "development") {
        console.log("Configuration loaded:", config.data);
      }
      setShouldRenderChildren(true);
    }
  }, [config]);

  const logout = () => {
    setShouldRenderChildren(false);
    setConfig(null);
    window.localStorage.removeItem("config");
    if (window.isNative) {
      // Reload the native app in order to kill the js context,
      // otherwise it will be reused by the next login
      sendMessage("RESET_WEBVIEW");
    }
    window.location.reload();
  };

  let configContext = {
    configData: config ? config.data : null,
    isIdle,
    setIsIdle,
    logout
  };

  return (
    <context.Provider value={configContext}>
      <Login
        isOpen={!shouldRenderChildren}
        isIdle={isIdle}
        onLogin={setConfig}
      />
      {shouldRenderChildren && children}
    </context.Provider>
  );
}

function useInteractionEvents() {
  let [lastInteraction, setLastInteraction] = useState(null);

  useEffect(() => {
    const updateInteraction = event => {
      setLastInteraction({ ts: performance.now(), event });
    };
    const options = { capture: false, passive: true };
    window.addEventListener("click", updateInteraction, options);
    window.addEventListener("keyup", updateInteraction, options);

    return () => {
      window.removeEventListener("click", updateInteraction, options);
      window.removeEventListener("keyup", updateInteraction, options);
    };
  }, []);

  return lastInteraction;
}

function useIsIdle(lastInteraction, secondsUntilIdle) {
  // Only use idle state on desktop
  let isDesktop = !window.isNative;
  let [isIdle, setIsIdle] = useState(isDesktop);

  useEffect(() => {
    if (isDesktop && lastInteraction && secondsUntilIdle) {
      setIsIdle(false);
      const timer = setTimeout(() => setIsIdle(true), secondsUntilIdle * 1000);
      return () => clearTimeout(timer);
    }
  }, [isDesktop, lastInteraction, secondsUntilIdle]);

  let [sessionStart, setSessionStart] = useState(null);
  useEffect(() => {
    if (window.isNative) return;

    const now = performance.now();

    if (!isIdle && sessionStart === null) {
      setSessionStart(now);
      logEvent("action", "idle", "session start", null, now);
    } else if (isIdle && sessionStart !== null) {
      setSessionStart(null);
      let durationMs = now - sessionStart;
      logEvent("action", "idle", "session end", { durationMs }, now);
    }
  }, [isIdle, sessionStart]);

  return [isIdle, setIsIdle];
}

function useClearCacheOnIdle(isIdle) {
  useEffect(() => {
    if (isIdle) {
      sendMessage("CLEAR_WEBFRAME_CACHE");
    }
  }, [isIdle]);
}
