import React, { useState, useRef, useEffect, useLayoutEffect } from "react";
import { AutoSizer, List } from "react-virtualized";
import { MdKeyboardArrowUp, MdKeyboardArrowDown } from "react-icons/md";

import ProductRow from "./product-row";
import { useCatalogFilter } from "../state/catalog-filter";
import { useSelectedProduct } from "../state/selected-product";
import { useConfiguration } from "../state/configuration";
import { easeInOutQuad } from "../utils/easing";
import styles from "./product-list.module.css";

export default function ProductList({ style }) {
  const numProductsVisible = 4.5;
  let { filteredCatalog, noResults } = useCatalogFilter();
  let { selectedProduct, setSelectedProduct } = useSelectedProduct();
  let { isIdle } = useConfiguration();
  let listRef = useRef(null);
  let [aspectRatio, setAspectRatio] = useState(1);

  let [scrollState, setScrollState] = useState({
    scrollTop: 0,
    clientHeight: 0,
    scrollHeight: 0
  });
  let [scrollIndices, setScrollIndices] = useState({
    startIndex: 0,
    stopIndex: 0
  });
  let [scrollerEnabled, setScrollerEnabled] = useState({
    up: false,
    down: true
  });
  let [isAnimating, setIsAnimating] = useState(false);

  useLayoutEffect(() => {
    if (filteredCatalog && filteredCatalog.length > 0) {
      // Determine a common thumbnail size for the virtualized list --
      // assume all default variant images in the filtered catalog will be of similar size
      let img = new Image();
      img.onload = () => setAspectRatio(img.naturalHeight / img.naturalWidth);
      img.src = filteredCatalog[0].variants[0].image.path;
    }
  }, [filteredCatalog]);

  useEffect(() => {
    setScrollState(state => {
      return { ...state, scrollTop: 0 };
    });
  }, [filteredCatalog, isIdle]);

  useEffect(() => {
    if (!isAnimating) {
      const { scrollTop, clientHeight, scrollHeight } = scrollState;
      if (clientHeight > 0 && scrollHeight > 0) {
        setScrollerEnabled({
          up: scrollTop !== 0,
          down: scrollTop + clientHeight < Math.floor(scrollHeight)
        });
      }
    } else {
      setScrollerEnabled({ up: false, down: false });
    }
  }, [scrollState, isAnimating]);

  const startScroll = (listRef, direction) => {
    if (!listRef) return;

    let scrollIndex =
      direction === "up"
        ? Math.max(0, scrollIndices.startIndex - Math.floor(numProductsVisible))
        : Math.min(
            filteredCatalog.length,
            scrollIndices.stopIndex + Math.floor(numProductsVisible)
          );

    let scrollOffset = listRef.current.getOffsetForRow({ index: scrollIndex });

    setIsAnimating(true);
    animateScroll(500, performance.now(), scrollState.scrollTop, scrollOffset);
  };

  const animateScroll = (
    duration,
    startTime,
    scrollTopInital,
    scrollTopFinal
  ) => {
    requestAnimationFrame(() => {
      const elapsed = performance.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const distance = scrollTopFinal - scrollTopInital;
      setScrollState({
        ...scrollState,
        scrollTop: scrollTopInital + distance * easeInOutQuad(progress)
      });

      if (elapsed < duration) {
        animateScroll(duration, startTime, scrollTopInital, scrollTopFinal);
      } else {
        setIsAnimating(false);
      }
    });
  };

  const getRowHeight = width => {
    // add 1em of padding on the left and right
    let em = document.documentElement.clientWidth / 100;
    let padding = 2 * 1 * em;
    return (width - padding) * aspectRatio;
  };

  const Row = ({ index, key, style }) => {
    let product = filteredCatalog[index];

    return (
      product &&
      selectedProduct && (
        <ProductRow
          key={key}
          style={style}
          product={product}
          selected={product.handle === selectedProduct.handle}
          onProductSelected={setSelectedProduct}
          visibleIndex={index - scrollIndices.startIndex}
        />
      )
    );
  };

  return (
    filteredCatalog &&
    !noResults && (
      <div className={styles.list} style={style}>
        <AutoSizer>
          {({ height, width }) => {
            let rowHeight = getRowHeight(width);
            let overscan = Math.floor(height / rowHeight);

            return (
              <List
                ref={listRef}
                height={height}
                width={width}
                rowCount={filteredCatalog.length}
                rowHeight={rowHeight}
                rowRenderer={Row}
                overscanRowCount={overscan}
                scrollTop={scrollState.scrollTop}
                onScroll={props => setScrollState(props)}
                onRowsRendered={props => setScrollIndices(props)}
              />
            );
          }}
        </AutoSizer>

        <div
          className={`${styles["scroller-up"]} ${
            !scrollerEnabled.up ? styles.disabled : ""
          }`}
          onClick={() =>
            scrollerEnabled.up ? startScroll(listRef, "up") : null
          }
        >
          <MdKeyboardArrowUp className={styles.icon} />
        </div>

        <div
          className={`${styles["scroller-down"]} ${
            !scrollerEnabled.down ? styles.disabled : ""
          }`}
          onClick={() =>
            scrollerEnabled.down ? startScroll(listRef, "down") : null
          }
        >
          <MdKeyboardArrowDown className={styles.icon} />
        </div>
      </div>
    )
  );
}
