import React, { useState, useEffect } from "react";
import { MdKeyboardArrowLeft } from "react-icons/md";

import Button from "./button";
import InfoMenu from "./info-menu";

import { logEvent } from "../utils/logging";

import styles from "./custom-rugs-menu.module.css";

export default function CustomRugsMenu({ product, variant, pricingEnabled }) {
  const [options, setOptions] = useState({});
  const [selectedOption, setSelectedOption] = useState(null);
  const [selectedVariant, setSelectedVariant] = useState(null);

  useEffect(() => {
    // get all treatments, based on the selected variant's size
    const treatments = product.variants
      .filter(v => v.size === variant.size)
      .map(v => v.treatment.split(" ")[0]);
    const images = product.images;
    const _options = {};
    // get options for all custom rug treatment types
    for (const image of images) {
      if (image.altText) {
        const [treatment, color] = image.altText.split("_");
        if (!treatments.includes(treatment)) continue;

        const option = { treatment, color, image };
        if (!(treatment in _options)) {
          _options[treatment] = [option];
        } else {
          _options[treatment].push(option);
        }
      }
    }

    setOptions(_options);
  }, [product, variant]);

  // automatically pick the option if there is only one
  useEffect(() => {
    if (
      Object.values(options).length === 1 &&
      Object.values(options)[0].length === 1
    ) {
      setSelectedOption(Object.values(options)[0][0]);
    }
  }, [options]);

  const handleClick = (e, option) => {
    setSelectedOption(option);
    const logValue = {
      product: product.title,
      treatment: option.treatment,
      color: option.color
    };
    logEvent(
      "click",
      "button",
      "custom rug edge treatment",
      logValue,
      e.timeStamp,
      e.clientX,
      e.clientY
    );
  };

  const ColorsRenderer = ({ treatment }) => {
    return (
      <div className={styles.colors}>
        {options[treatment].map((option, i) => {
          return (
            <div key={i} className={styles.color}>
              <img
                src={option.image.path}
                alt={option.color}
                onClick={e => handleClick(e, option)}
              />
              <div className={styles.label}>{option.color}</div>
            </div>
          );
        })}
      </div>
    );
  };

  // Determine the correct variant from the selected option
  useEffect(() => {
    if (!selectedOption) return;

    let _variant = product.variants.find(v => {
      return (
        v.treatment.includes(selectedOption.treatment) &&
        v.size === variant.size
      );
    });

    setSelectedVariant(_variant);
  }, [selectedOption, product, variant]);

  const getExtraVariantText = () => {
    let text = "";
    if (selectedOption.treatment) text += ` | ${selectedOption.treatment}`;
    if (selectedOption.color) text += ` | ${selectedOption.color}`;

    return text;
  };

  return !selectedOption || !selectedVariant ? (
    <div className={styles.contents}>
      <h1 className={styles.prompt}>Select a rug finish to continue:</h1>
      {Object.keys(options).map(treatment => {
        return (
          <React.Fragment key={treatment}>
            <div className={styles.treatment}>{treatment}</div>
            <ColorsRenderer treatment={treatment} />
          </React.Fragment>
        );
      })}
    </div>
  ) : (
    <div>
      <Button
        style={{ position: "absolute", top: "2em", left: "2em" }}
        onClick={() => {
          setSelectedOption(null);
          setSelectedVariant(null);
        }}
      >
        <MdKeyboardArrowLeft className={styles.icon} /> Back
      </Button>
      <InfoMenu
        product={product}
        variant={selectedVariant}
        customImage={selectedOption.image}
        extraVariantText={getExtraVariantText()}
        pricingEnabled={pricingEnabled}
      />
    </div>
  );
}
