import React, { useState, useContext, useEffect, useRef } from "react";
import Keyboard from "react-simple-keyboard";

import { useOnClickOutside } from "../utils/hooks";

const context = React.createContext({
  setIsActive: () => {},
  setInputField: () => {},
  setInputValue: () => {},
  setOnChangeCallback: () => {},
  setOnSubmitCallback: () => {}
});

export const useKeyboard = () => useContext(context);

export function KeyboardProvider({ children }) {
  let kbRef = useRef(null);
  const [isActive, setIsActive] = useState(false);
  const [inputField, setInputField] = useState(null);
  const [inputValue, setInputValue] = useState("");
  const [onChangeCallback, setOnChangeCallback] = useState(null);
  const [onSubmitCallback, setOnSubmitCallback] = useState(null);

  useEffect(() => {
    if (isActive && inputField) {
      const html = document.getElementsByTagName("html")[0];
      const appHeight = document.getElementById("app-container").offsetHeight;
      const kbHeight = document.getElementsByClassName(
        "react-simple-keyboard"
      )[0].offsetHeight;
      const windowHeight = appHeight - kbHeight;
      const inputHeight = inputField?.getBoundingClientRect()?.y;
      const top = inputHeight - windowHeight + kbHeight;
      if (top) html.scrollTo({ top, behavior: "smooth" });
    }
  }, [isActive, inputField]);

  useEffect(() => {
    if (isActive) {
      kbRef.current.setInput(inputValue);
    }
  }, [isActive, inputValue]);

  const [isCapsOn, setIsCapsOn] = useState(false);
  const [layoutName, setLayoutName] = useState("default");

  const handleKeypress = key => {
    switch (key) {
      case "{shift}":
        setLayoutName(layoutName === "default" ? "shift" : "default");
        break;
      case "{lock}":
        setLayoutName(layoutName === "default" ? "shift" : "default");
        setIsCapsOn(!isCapsOn);
        break;
      case "{enter}":
        if (onSubmitCallback) onSubmitCallback();
        break;
      default:
        setLayoutName(isCapsOn ? "shift" : "default");
        break;
    }
  };

  useOnClickOutside(kbRef.current?.keyboardDOM, () => {
    setIsActive(false);
  });

  const kbContext = {
    setIsActive,
    setInputField,
    setInputValue,
    setOnChangeCallback,
    setOnSubmitCallback
  };

  return (
    <context.Provider value={kbContext}>
      <div
        id="app-container"
        style={{ width: "100vw", height: "100vh", display: "flex" }}
      >
        {children}
      </div>
      {isActive && (
        <Keyboard
          keyboardRef={ref => (kbRef.current = ref)}
          layoutName={layoutName}
          onChange={onChangeCallback}
          onKeyPress={handleKeypress}
          preventMouseDownDefault
          disableButtonHold
          display={{
            "{bksp}": "←",
            "{tab}": "tab",
            "{lock}": "caps",
            "{shift}": "shift",
            "{space}": " ",
            "{enter}": "↲"
          }}
          layout={{
            default: [
              "` 1 2 3 4 5 6 7 8 9 0 - = {bksp}",
              "q w e r t y u i o p [ ] \\",
              "{lock} a s d f g h j k l ; ' {enter}",
              "{shift} z x c v b n m , . / {shift}",
              "@ {space} .com"
            ],
            shift: [
              "~ ! @ # $ % ^ & * ( ) _ + {bksp}",
              "Q W E R T Y U I O P { } |",
              '{lock} A S D F G H J K L : " {enter}',
              "{shift} Z X C V B N M < > ? {shift}",
              "@ {space} .com"
            ]
          }}
        />
      )}
    </context.Provider>
  );
}
