import React, { useState, useContext, useEffect, useCallback } from "react";

import { useCatalog } from "./catalog";
import { useConfiguration } from "./configuration";
import { logEvent } from "../utils/logging";

const context = React.createContext({
  filteredCatalog: [],
  collectionFilters: [],
  activeCollection: null,
  setActiveCollection: () => {},
  searchValue: "",
  setSearchValue: () => {},
  filters: [],
  activeFilters: [],
  availableFilters: [],
  setActiveFilters: () => {},
  resetActiveCollection: () => {},
  resetActiveFilters: () => {},
  resetSearch: () => {},
  noResults: false
});

export const useCatalogFilter = () => useContext(context);

export function CatalogFilterProvider({ children }) {
  let { catalog } = useCatalog();
  let { configData, isIdle } = useConfiguration();

  let collectionFilters = useCollectionFilters(
    catalog,
    configData.collectionFilters || []
  );
  let [activeCollection, setActiveCollection] = useState(null);

  let initialFilters = useCallback(getInitialFilters(configData.tagFilters), [
    configData
  ]);
  let [activeFilters, setActiveFilters] = useState(initialFilters);

  const resetActiveCollection = useCallback(
    () => collectionFilters.length > 0 && setActiveCollection(null),
    [collectionFilters]
  );

  const resetActiveFilters = useCallback(
    () => setActiveFilters(initialFilters),
    [initialFilters]
  );

  const resetSearch = useCallback(() => setSearchValue(""), []);

  useResetOnIdle(
    resetActiveCollection,
    resetActiveFilters,
    resetSearch,
    isIdle
  );

  let [searchValue, setSearchValue] = useState("");
  useDirectSearchInput(
    setSearchValue,
    setActiveCollection,
    collectionFilters,
    resetActiveFilters
  );

  let collectionCatalog = useCollectionCatalog(catalog, activeCollection);
  let filters = useTagFilters(
    initialFilters,
    configData.tagFilters,
    collectionCatalog
  );

  let { filteredCatalog, noResults } = useFilteredCatalog(
    collectionCatalog,
    searchValue,
    activeFilters,
    configData.tagFilters
  );

  let availableFilters = useTagFilters(
    initialFilters,
    configData.tagFilters,
    filteredCatalog
  );

  useLogging(
    catalog,
    filteredCatalog,
    activeCollection,
    activeFilters,
    searchValue,
    noResults
  );

  let catalogFilterContext = {
    filteredCatalog,
    collectionFilters,
    activeCollection,
    setActiveCollection,
    searchValue,
    setSearchValue,
    filters,
    activeFilters,
    availableFilters,
    setActiveFilters,
    resetActiveCollection,
    resetActiveFilters,
    resetSearch,
    noResults
  };

  return (
    <context.Provider value={catalogFilterContext}>{children}</context.Provider>
  );
}

function getInitialFilters(tagFilters) {
  let filters = {};
  for (const tf of tagFilters) {
    filters[tf.value] = [];
  }
  return filters;
}

function useResetOnIdle(
  resetActiveCollection,
  resetActiveFilters,
  resetSearch,
  isIdle
) {
  useEffect(() => {
    if (isIdle) {
      const reset = () => {
        resetActiveCollection();
        resetActiveFilters();
        resetSearch();
      };

      if (window.isNative) {
        reset();
      } else {
        // Delay resetting to
        // 1 - allow the user a moment to cancel idling, and
        // 2 - prevent fps drops on the screensaver & collection picker transition
        let delay = setTimeout(reset, 2000);

        return () => clearTimeout(delay);
      }
    }
  }, [isIdle, resetActiveCollection, resetActiveFilters, resetSearch]);
}

function useCollectionFilters(catalog, filters) {
  let [collectionFilters, setCollectionFilters] = useState([]);

  useEffect(() => {
    const catalogCollections = new Set();
    catalog.forEach(product => {
      product.collections.forEach(collection => {
        catalogCollections.add(collection);
      });
    });
    setCollectionFilters(
      filters.filter(collection => catalogCollections.has(collection.value))
    );
  }, [catalog, filters]);

  return collectionFilters;
}

function getFiltersForCatalog(tagFilters, catalog) {
  let uniqueTags = {};

  for (const tf of tagFilters) {
    uniqueTags[tf.value] = new Set();
  }

  catalog.forEach(product => {
    product.tags.forEach(tag => {
      for (const tf of tagFilters) {
        if (
          tag.startsWith(tf.prefix) &&
          tag.includes("_") &&
          !tag.endsWith("_")
        ) {
          uniqueTags[tf.value].add(tag);
          break;
        }
      }
    });
  });

  const compareLabels = (a, b) => {
    const isSize = s => /[0-9] ?x ?[0-9]/.test(s);

    if (!isSize(a.label) || !isSize(b.label)) {
      return a.label < b.label ? -1 : 1;
    }

    const getArea = size =>
      parseInt(size.split("x", 2)[0]) * parseInt(size.split("x", 2)[1]);

    let _a = a.label.match(/^\d/) ? getArea(a.label) : a.label;
    let _b = b.label.match(/^\d/) ? getArea(b.label) : b.label;

    if (typeof _a === "number" && typeof _b === "number") {
      return _a < _b ? -1 : 1;
    } else if (typeof _a === "string" && typeof _b === "string") {
      return _a < _b ? -1 : 1;
    } else {
      return typeof _a === "number" ? -1 : 1;
    }
  };

  const createFilterFromTag = tag => {
    return {
      label: tag.split("_", 2)[1],
      value: tag
    };
  };

  let filters = {};
  for (const tf of tagFilters) {
    filters[tf.value] = Array.from(uniqueTags[tf.value])
      .map(tag => createFilterFromTag(tag))
      .sort(compareLabels);
  }

  return filters;
}

function useTagFilters(initialFilters, tagFilters, catalog) {
  let [filters, setFilters] = useState(initialFilters);

  useEffect(() => {
    const catalogFilters = getFiltersForCatalog(tagFilters, catalog);
    if (catalogFilters) {
      setFilters(catalogFilters);
    }
  }, [tagFilters, catalog]);

  return filters;
}

function useCollectionCatalog(catalog, activeCollection) {
  let [collectionCatalog, setCollectionCatalog] = useState(catalog);

  useEffect(() => {
    if (catalog && catalog.length > 0 && activeCollection !== null) {
      setCollectionCatalog(
        catalog.filter(product => {
          return product.collections.includes(activeCollection.value);
        })
      );
    }
  }, [catalog, activeCollection]);

  return collectionCatalog;
}

/**
 * The core filtering "logic". Will most likely need to be replaced by a service-worker alternative
 * if performance and flexibility becomes a concern in the future.
 */
function useFilteredCatalog(catalog, searchValue, activeFilters, tagFilters) {
  let [filteredCatalog, setFilteredCatalog] = useState(catalog);
  let [noResults, setNoResults] = useState(false);

  useEffect(() => {
    function filter() {
      if (catalog && catalog.length > 0) {
        let _filteredCatalog = catalog.filter(product => {
          for (const tf of tagFilters) {
            const hasTag =
              activeFilters[tf.value].length === 0 ||
              activeFilters[tf.value].every(filter =>
                product.tags.includes(filter.value)
              );
            if (!hasTag) {
              return false;
            }
          }

          const searchTerms =
            searchValue.trim() === ""
              ? []
              : searchValue.toLowerCase().split(" ");
          if (searchTerms.length > 0) {
            const objToSearch = JSON.stringify([
              product.title,
              product.tags,
              product.variants.map(variant => {
                return { size: variant.size, sku: variant.sku };
              })
            ]).toLowerCase();
            return searchTerms.every(
              term => objToSearch.indexOf(term.trim()) !== -1
            );
          }

          return true;
        });

        if (_filteredCatalog && _filteredCatalog.length === 0) {
          setFilteredCatalog(catalog);
          setNoResults(true);
        } else {
          setFilteredCatalog(_filteredCatalog);
          setNoResults(false);
        }
      }
    }

    // Debounce
    const delay = setTimeout(() => filter(), 150);
    return () => clearTimeout(delay);
  }, [catalog, searchValue, activeFilters, tagFilters]);

  return { filteredCatalog, noResults };
}

/**
 * Allows for a USB scanner to be plugged in and used as direct input to the search field.
 *
 * Inputs are stored in a buffer and only applied if they are fast enough, otherwise discarded.
 */
function useDirectSearchInput(
  setSearchValue,
  setActiveCollection,
  collectionFilters,
  resetActiveFilters
) {
  let [buffer, setBuffer] = useState("");
  let [lastInput, setLastInput] = useState(null);

  const delay = 100;

  useEffect(() => {
    const recordInput = e => {
      let now = performance.now();
      if (buffer === "" || !lastInput || now - lastInput < delay) {
        let inp = String.fromCharCode(e.keyCode);
        if (/[a-zA-Z0-9 ]/.test(inp)) {
          setBuffer(b => b + inp);
        }
      }
      setLastInput(now);
    };
    const options = { capture: false, passive: true };
    window.addEventListener("keyup", recordInput, options);

    return () => window.removeEventListener("keyup", recordInput, options);
  }, [buffer, lastInput]);

  useEffect(() => {
    const applyBuffer = setTimeout(() => {
      if (buffer.length >= 10) {
        setActiveCollection(collectionFilters[0]);
        resetActiveFilters();
        setSearchValue(buffer.toLowerCase());
        console.log(`Searched: ${buffer.toLowerCase()}`);
      }
      setBuffer("");
    }, delay);

    return () => clearTimeout(applyBuffer);
  }, [
    buffer,
    setBuffer,
    setSearchValue,
    setActiveCollection,
    collectionFilters,
    resetActiveFilters
  ]);
}

function useLogging(
  catalog,
  filteredCatalog,
  activeCollection,
  activeFilters,
  searchValue,
  noResults
) {
  useEffect(() => {
    let loggingDelay;

    if (activeCollection && catalog.length > 0 && filteredCatalog.length > 0) {
      if (catalog.length !== filteredCatalog.length) {
        // return only an array of labels for a group of labels,
        // instead of { label, value }[]
        let formattedFilters = {};
        for (const p in activeFilters) {
          formattedFilters[p] = activeFilters[p].map(filter =>
            filter ? filter.label : null
          );
        }

        const filterData = {
          activeCollection: activeCollection.label,
          activeFilters: formattedFilters,
          searchValue,
          resultCount: noResults ? 0 : filteredCatalog.length
        };
        loggingDelay = setTimeout(() => {
          logEvent(
            "action",
            "filter",
            "catalog",
            filterData,
            performance.now()
          );
        }, 1000);

        return () => clearTimeout(loggingDelay);
      }
    }
  }, [
    catalog,
    filteredCatalog,
    activeCollection,
    activeFilters,
    searchValue,
    noResults
  ]);
}
