import { CosmosClient } from "@azure/cosmos";
import { getLoggingResourceToken } from "./service-api";
import { version } from "../../package.json";

let dbClient = null;
let clientId = null;
const ua = navigator.userAgent;
const viewport = `${window.innerWidth}x${window.innerHeight}`;
const isDev =
  process.env.NODE_ENV === "development" || version.includes("-dev");
const env = isDev
  ? "development"
  : version.includes("-rc")
  ? "prerelease"
  : "production";

/**
 * Logs an event to Cosmos DB, for usage analytics.
 *
 * @param {string} type Either 'click' or 'action'.
 * @param {string} category The type of element clicked, or the type of action that was
 * completed.
 * @param {string} label A human-readable identifier for the `target`. Usually the label
 * shown to the user.
 * @param {*} value A value for the event.
 * @param {DOMHighResTimeStamp} timestamp The time the event was triggered.
 */
export async function logEvent(
  type,
  category,
  label,
  value,
  timestamp,
  x = null,
  y = null
) {
  if (window.isNative) return;
  // ensure the client id has been set before logging
  if (clientId === null) {
    const config = window.localStorage.getItem("config");

    if (!config) {
      return;
    } else {
      clientId = JSON.parse(atob(config)).data.id;
    }
  }

  const token = await getLoggingResourceToken();
  if (token === null) return;

  const containerLink = Object.keys(token)[0];
  // the link will be in the form dbs/[db]/colls/[container]
  const resourceLinkPattern = new RegExp(/dbs\/(.[^/]+)\/colls\/(.[^/]+)/);
  const [databaseId, containerId] = containerLink
    .match(resourceLinkPattern)
    .slice(1, 3);

  if (dbClient === null) {
    dbClient = new CosmosClient({
      endpoint: "https://kiosk-cosmosdb.documents.azure.com:443/",
      resourceTokens: token
    });
  }

  const queueTime = timestamp ? Math.floor(performance.now() - timestamp) : 0;

  const event = {
    clientId,
    type,
    category,
    label,
    value,
    viewport,
    x: x || undefined,
    y: y || undefined,
    queueTime,
    env,
    version,
    ua
  };

  try {
    await dbClient
      .database(databaseId)
      .container(containerId)
      .items.upsert(event);
  } catch (error) {
    console.error(`Error logging: ${error}`);
  }
}
