import React, { useState } from "react";

import EmailButton from "./email-button";
import SmsButton from "./sms-button";
import QrButton from "./qr-button";

/**
 * Interactable components for transferring a URL from the kiosk to a mobile device, via a
 * combination of SMS, email, or QR code, depending on which prompts are provided.
 */
export default function WebOptions({
  url,
  smsMessage = "",
  emailSubject = "",
  emailMessage = "",
  qrCodePrompt = ""
}) {
  let [errorMessage, setErrorMessage] = useState("");

  return (
    <>
      <SmsButton
        style={{ marginTop: "1em" }}
        message={smsMessage}
        onError={setErrorMessage}
      />

      <EmailButton
        style={{ marginTop: "1em" }}
        subject={emailSubject}
        message={emailMessage}
        onError={setErrorMessage}
        loggingLabel={"checkout link"}
        loggingValue={url}
      />

      <QrButton style={{ marginTop: "1em" }} url={url} prompt={qrCodePrompt} />

      {errorMessage && <div style={{ marginTop: "1em" }}>{errorMessage}</div>}
    </>
  );
}
