export default function availableQuantityText(
  variant,
  showAvailableQuantity = false
) {
  if (!variant) {
    return "";
  }

  if (
    !variant.availableForSale ||
    !showAvailableQuantity ||
    !("quantityAvailable" in variant) ||
    variant.quantityAvailable <= 1
  ) {
    return "Call for availability.";
  } else {
    return `${variant.quantityAvailable} in stock.`;
  }
}
