import React from "react";

import availableQuantityText from "../utils/availableQuantityText";

import styles from "./variant-info.module.css";

export default function VariantInfo({
  product,
  variant,
  customImage,
  extraVariantText,
  showTitle = true,
  showVariantTitle = true,
  showSku = true,
  showAvailableQuantity = true
}) {
  const formatSize = size => size.replace("x", " ⨯ ");

  return (
    <div className={styles.wrapper}>
      <img
        className={styles.image}
        alt={
          customImage
            ? customImage.altText
            : variant.image.altText || "no description"
        }
        src={customImage ? customImage.path : variant.image.path}
      />

      {showTitle && <h1 className={styles.title}>{product.title}</h1>}

      {showVariantTitle && (
        <div className={styles["variant-info"]}>
          {showVariantTitle && formatSize(variant.size)}
          {extraVariantText && <>{extraVariantText}</>}
        </div>
      )}

      {showAvailableQuantity && (
        <div style={{ marginTop: "0.5rem" }}>
          <i>{availableQuantityText(variant, showAvailableQuantity)}</i>
        </div>
      )}

      {showSku && (
        <div style={{ marginTop: "0.5rem", fontSize: "0.75em" }}>
          {variant.sku}
        </div>
      )}
    </div>
  );
}
