import React, { useState, useEffect } from "react";
import Loading from "./loading";
import {
  sendMessage,
  addListener,
  removeListener
} from "../utils/window-messaging";

import styles from "./electron-update-status.module.css";

export default function ElectronUpdateStatus({ onUpdated = () => {} }) {
  const [text, setText] = useState("");
  useEffect(() => {
    const updateRequestTimeout = setTimeout(() => {
      onUpdated();
    }, 1000);

    const handleStatus = ({ status, progress }) => {
      clearTimeout(updateRequestTimeout);
      console.log(`Electron update status: ${status}; progress: ${progress}`);
      switch (status) {
        case "checking-for-update":
          setText("Checking for app updates...");
          break;
        case "update-available":
          setText("An update was found. Downloading...");
          break;
        case "update-downloaded":
          setText("Update downloaded. The app will restart soon.");
          break;
        case "update-not-available":
          onUpdated();
          break;
        default:
          console.error("Unexpected update status:", status);
          onUpdated();
          break;
      }
    };

    addListener("ELECTRON_UPDATE_STATUS", handleStatus);

    sendMessage("START_ELECTRON_UPDATES");

    return () => {
      removeListener("ELECTRON_UPDATE_STATUS", handleStatus);
    };
  });

  return <div className={styles.wrapper}>{<Loading text={text} />}</div>;
}
