import React from "react";

import Button from "../components/button";
import { useSelectedProduct } from "../state/selected-product";
import { useConfiguration } from "../state/configuration";
import { sendMessage } from "../utils/window-messaging";
import styles from "./visualizer-button.module.css";

/**
 * For the React Native implementation only.
 * Makes a request to show the selected variant in the Covered By Rugs visualizer.
 */
export default function VisualizerButton() {
  let { selectedProduct } = useSelectedProduct();
  let { configData } = useConfiguration();

  const getURL = () => {
    let baseURL = "https://www.coveredbyrugs.com/products/";
    let params = "?view=kiosk-visualizer";
    return `${baseURL}${selectedProduct.handle}${params}`;
  };

  const handleClick = e => {
    sendMessage("REQUEST_WEBVIEW", getURL());
  };

  return (
    window.isNative &&
    configData.visualizerEnabled && (
      <Button className={styles.button} onClick={handleClick}>
        See in Visualizer
      </Button>
    )
  );
}
