export const IMAGE_TYPES = {
  MAIN: "main",
  SCENE: "scene",
  FIBER: "fiber",
  PILE: "pile",
  CORNER: "corner",
  BACKING: "backing",
  TEXTURE: "texture",
  ROLL: "roll"
};

export function getAllProducts() {
  let config = JSON.parse(atob(window.localStorage.getItem("config")));

  if (window.isNative && config.data.products.url === "trial-products.json") {
    return Promise.resolve(require("../native/trial-products.json"));
  }

  return fetch(config.data.products.url, {
    method: "GET",
    headers: { "Cache-Control": "private, max-age=0" }
  })
    .then(res => res.json())
    .catch(err => {
      return Promise.reject(
        "Unable to obtain product data. " +
          "The connection either timed out, or is inaccessible."
      );
    });
}
