import React from "react";
import { MdSearch } from "react-icons/md";

import Input from "./input";
import { useCatalogFilter } from "../state/catalog-filter";

export default function SearchInput({ className = "", style = {} }) {
  let { filteredCatalog, searchValue, setSearchValue } = useCatalogFilter();

  const handleSearchChange = e => {
    let inputStr = e.target.value;
    inputStr = inputStr.slice(0, 100);
    setSearchValue(inputStr);
  };

  const handleSearchClear = () => {
    setSearchValue("");
  };

  return (
    <Input
      className={className}
      style={style}
      borderless
      icon={<MdSearch style={{ width: "1.6em", height: "1.6em" }} />}
      placeholder={`Search ${filteredCatalog.length} products...`}
      value={searchValue}
      onChange={handleSearchChange}
      clearEnabled
      onClear={handleSearchClear}
    />
  );
}
