import React, { useState, useEffect } from "react";
import { MdKeyboardArrowLeft, MdKeyboardArrowRight } from "react-icons/md";
import SwipeableViews from "react-swipeable-views";
import { virtualize } from "react-swipeable-views-utils";
import { mod } from "react-swipeable-views-core";

import { useSelectedProduct } from "../state/selected-product";
import { useUpdateStatus } from "../state/update-status";
import { IMAGE_TYPES } from "../utils/products-api";
import styles from "./product-scene.module.css";

const VirtualizeSwipeableViews = virtualize(SwipeableViews);

export default function ProductScene() {
  let {
    selectedProduct,
    selectedVariant,
    shouldFocusVariant
  } = useSelectedProduct();
  // Need to refresh the image if it changed from a catalog update
  // include `lastUpdatedAt` in the src
  let { lastUpdatedAt } = useUpdateStatus();
  let [images, setImages] = useState([]);
  let [slideIndex, setSlideIndex] = useState(0);

  useEffect(() => {
    const imageTypes = [
      IMAGE_TYPES.SCENE,
      IMAGE_TYPES.FIBER,
      IMAGE_TYPES.CORNER,
      IMAGE_TYPES.PILE,
      IMAGE_TYPES.BACKING,
      IMAGE_TYPES.ROLL
    ];

    const compareImageOrder = (a, b) => {
      return imageTypes.indexOf(a.type) - imageTypes.indexOf(b.type);
    };

    if (selectedProduct && selectedVariant) {
      let supportingImages = selectedProduct.images
        .slice()
        .filter(image => image.type && imageTypes.includes(image.type))
        .sort(compareImageOrder);

      // Place variant image into the first position, so that when a variant
      // is selected, the viewer only has to swipe left one place
      setImages([selectedVariant.image, ...supportingImages]);
    }
  }, [selectedProduct, selectedVariant]);

  useEffect(() => {
    if (shouldFocusVariant) {
      // A variant was manually selected
      setSlideIndex(0);
    } else {
      // The product was selected from the product list;
      // default to the first supporting image
      setSlideIndex(1);
    }
  }, [images, shouldFocusVariant]);

  const slideRenderer = ({ index, key }) => {
    const i = mod(index, images.length);
    return (
      <div key={key} className={styles.scene}>
        <img
          className={`${styles["scene-image"]} ${i === 0 ? styles.main : ""}`}
          alt={images[i].altText || "no description"}
          src={`${images[i].path}?${lastUpdatedAt}`}
        />
      </div>
    );
  };

  return (
    selectedProduct &&
    images.length > 0 && (
      <div className={styles.scene}>
        <VirtualizeSwipeableViews
          containerStyle={{ height: "100%" }}
          slideClassName={styles.slide}
          hysteresis={0.1}
          index={slideIndex}
          overscanSlideAfter={1}
          overscanSlideBefore={1}
          slideRenderer={slideRenderer}
          onChangeIndex={index => setSlideIndex(index)}
          enableMouseEvents
        />

        <div
          className={`${styles.overlay} ${styles.left}`}
          onClick={() => setSlideIndex(i => i - 1)}
        >
          <MdKeyboardArrowLeft className={styles.icon} />
        </div>

        <div
          className={`${styles.overlay} ${styles.right}`}
          onClick={() => setSlideIndex(i => i + 1)}
        >
          <MdKeyboardArrowRight className={styles.icon} />
        </div>

        <div className={styles["indicator-dots"]}>
          {images.map((_, index) => {
            let currentIndex = mod(slideIndex, images.length);

            return (
              <div
                key={index}
                className={`${styles.dot} ${
                  index === currentIndex ? styles.selected : ""
                }`}
                onClick={() => setSlideIndex(index)}
              >
                <div />
              </div>
            );
          })}
        </div>
      </div>
    )
  );
}
