import React, { useRef, useState, useEffect } from "react";
import { MdChatBubbleOutline, MdDone } from "react-icons/md";

import Button from "./button";
import Input from "./input";
import Loading from "./loading";
import { useOnClickOutside } from "../utils/hooks";
import { sendSms } from "../utils/service-api";
import styles from "./sms-button.module.css";

export default function SmsButton({
  inverted = false,
  className = "",
  style = {},
  message,
  keepActive = false,
  onError
}) {
  let smsRef = useRef();
  useOnClickOutside(smsRef, () => !keepActive && setIsSmsActive(false));

  let [smsValue, setSmsValue] = useState("");
  const handleSmsChange = e => {
    let digits = e.target.value.replace(/\D/g, "");
    digits =
      digits.slice(0, 3) + " " + digits.slice(3, 6) + " " + digits.slice(6, 10);
    setSmsValue(digits.trim());
    onError("");
  };

  let [isSmsActive, setIsSmsActive] = useState(false);
  useEffect(() => {
    if (!isSmsActive) {
      setSmsValue("");
    } else {
      onError("");
    }
  }, [isSmsActive, onError]);

  useEffect(() => {
    if (keepActive && !isSmsActive) {
      setIsSmsActive(true);
    }
  }, [keepActive, isSmsActive]);

  let [smsSent, setSmsSent] = useState(null);
  useEffect(() => {
    if (smsSent) {
      const sentTimer = setTimeout(() => setSmsSent(null), 3000);
      return () => clearTimeout(sentTimer);
    }
  }, [smsSent]);

  const sendProductSms = () => {
    setSmsSent(false);
    if (!keepActive) {
      setIsSmsActive(false);
    }
    let phoneNum = smsValue.replace(/ /g, "");
    if (phoneNum.length === 10) {
      sendSms(`+1${phoneNum}`, message)
        .then(() => setSmsSent(true))
        .catch(() => {
          setSmsSent(null);
          onError("Unable to send text message.");
        });
    } else {
      setSmsSent(null);
      onError("Invalid phone number.");
    }
  };

  return (
    message && (
      <div
        ref={smsRef}
        className={`${styles.sms} ${
          isSmsActive ? styles.active : ""
        } ${className}`}
        style={style}
      >
        {!isSmsActive ? (
          <Button
            inverted={inverted}
            style={{ minWidth: "10em" }}
            onClick={() => {
              smsSent === null && setIsSmsActive(true);
            }}
          >
            {smsSent === null ? (
              <>
                <MdChatBubbleOutline className={styles["left-icon"]} /> Text
                (SMS)
              </>
            ) : smsSent === true ? (
              <>
                <MdDone className={styles["left-icon"]} /> Sent!
              </>
            ) : (
              <Loading color={"var(--color-text-inverted)"} />
            )}
          </Button>
        ) : (
          <Input
            borderless={inverted}
            icon={<MdChatBubbleOutline className={styles.icon} />}
            buttonIcon={<span>Submit</span>}
            placeholder="123 987 6543"
            value={smsValue}
            onChange={handleSmsChange}
            onSubmit={sendProductSms}
          />
        )}
      </div>
    )
  );
}
