import React from "react";

import Fade from "../animations/fade";
import CheckboxGroup from "./checkbox-group";
import { useCatalogFilter } from "../state/catalog-filter";
import { useConfiguration } from "../state/configuration";
import styles from "./catalog-filter-menu.module.css";

export default function CatalogFilterMenu({
  wrapperClassName = "",
  wrapperStyle,
  className = "",
  style
}) {
  let { configData } = useConfiguration();

  let {
    filters,
    activeFilters,
    availableFilters,
    setActiveFilters,
    noResults
  } = useCatalogFilter();

  return (
    <div className={`${styles.menu} ${wrapperClassName}`} style={wrapperStyle}>
      <div
        className={`${styles["filters-wrapper"]} ${className}`}
        style={style}
      >
        <div className={styles.filters}>
          {configData.tagFilters.map(tagFilter => (
            <React.Fragment key={tagFilter.value}>
              <div className={styles["filter-label"]}>{tagFilter.label}</div>
              <CheckboxGroup
                style={{ marginTop: "0.5em" }}
                defaultItemLabel={`All ${tagFilter.label}`}
                items={filters[tagFilter.value]}
                selectedItems={activeFilters[tagFilter.value]}
                availableItems={availableFilters[tagFilter.value]}
                onChange={items => {
                  let newFilters = { ...activeFilters };
                  newFilters[tagFilter.value] = items;
                  setActiveFilters(newFilters);
                }}
              />
            </React.Fragment>
          ))}
        </div>

        <Fade className={styles["no-results"]} in={noResults} duration={250}>
          <div>
            <h1>No results found.</h1>
            <p>Please modify or reset your search.</p>
          </div>
        </Fade>
      </div>
    </div>
  );
}
