import React, { useEffect } from "react";

import Fade from "../animations/fade";
import Button from "../components/button";
import ConfigButton from "../components/config-button";
import { useConfiguration } from "../state/configuration";
import { useCatalog } from "../state/catalog";
import { useCatalogFilter } from "../state/catalog-filter";
import { useUpdateStatus, UPDATE_STATUS } from "../state/update-status";
import styles from "./no-catalog.module.css";

export default function NoCatalog() {
  let { catalog, hasDownloadConsent, grantDownloadConsent } = useCatalog();
  let { collectionFilters } = useCatalogFilter();
  let { setIsIdle, configData } = useConfiguration();

  // Show if there's no catalog, and if there's no collection filters.
  // The latter condition will trigger upon switching logins when
  // the app is downloading a catalog for the new login. There will be
  // an old catalog still loaded, but it would've belonged to the previous login.
  let show =
    (catalog && catalog.length === 0) ||
    (collectionFilters && collectionFilters.length === 0);

  // Force load the new catalog ASAP if the current one belonged to the previous login.
  let { updateStatus } = useUpdateStatus();
  useEffect(() => {
    if (show && updateStatus.status === UPDATE_STATUS.STAGED) {
      setIsIdle(true);
    }
  }, [show, updateStatus, setIsIdle]);

  return (
    <Fade className={styles.overlay} in={show} duration={500}>
      {window.isNative && updateStatus.status === UPDATE_STATUS.NOT_CHECKED ? (
        <>
          <div className={styles.info}>
            Would you like to download this catalog?
            <br />
            This may take up to {configData.catalogSize} of storage.
          </div>

          {!hasDownloadConsent &&
            <Button
              style={{ marginTop: "1em" }}
              inverted
              onClick={() => grantDownloadConsent()}
            >
              Download
            </Button>
          }

          <ConfigButton
            style={{
              position: "absolute",
              bottom: "1rem",
              left: "1rem"
            }}
          />
        </>
      ) : (
          <div className={styles.info}>{updateStatus.details}</div>
        )}
    </Fade>
  );
}
