import React, { useState, useRef } from "react";
import { MdTune, MdClose, MdHome } from "react-icons/md";

import Fade from "../animations/fade";
import Button from "./button";
import SearchInput from "./search-input";
import CatalogFilterMenu from "./catalog-filter-menu";
import { useCatalogFilter } from "../state/catalog-filter";
import { useOnClickOutside } from "../utils/hooks";

import styles from "./catalog-filter-mini.module.css";

export default function CatalogFilterButton({ className = "", style }) {
  let [isMenuActive, setIsMenuActive] = useState(false);
  let {
    noResults,
    resetActiveCollection,
    resetActiveFilters,
    resetSearch
  } = useCatalogFilter();

  let menuRef = useRef();
  useOnClickOutside(menuRef, () => setIsMenuActive(false));

  let showMenu = isMenuActive || noResults;

  return (
    <>
      <Fade
        in={showMenu}
        className={styles.overlay}
        duration={250}
        opacity={0.5}
      >
        <div />
      </Fade>
      <div
        ref={menuRef}
        className={`${styles.wrapper} ${className}`}
        style={style}
      >
        <div className={`${styles.triggers} ${showMenu ? styles.active : ""}`}>
          <Button
            alt
            inverted
            onClick={() => {
              resetActiveCollection();
              resetActiveFilters();
              resetSearch();
            }}
            loggingLabel={"home"}
          >
            <MdHome className={styles["button-icon"]} />
            <div style={{ marginLeft: "0.5em" }}>Home</div>
          </Button>

          <SearchInput className={styles.search} />

          <Button
            inverted
            onClick={() => setIsMenuActive(!isMenuActive)}
            loggingLabel={
              !showMenu ? "filter menu opened" : "filter menu closed"
            }
          >
            {!showMenu ? (
              <>
                <MdTune className={styles["button-icon"]} />
                <div className={styles["button-label"]}>Filter</div>
              </>
            ) : (
              <>
                <MdClose className={styles["button-icon"]} />
                <div className={styles["button-label"]}>Done</div>
              </>
            )}
          </Button>
        </div>

        {/* The calc() here is to account for the height of the top bar */}
        <Fade
          in={showMenu}
          duration={250}
          style={{ maxHeight: "calc(100vh - 4.4em)" }}
        >
          <CatalogFilterMenu
            wrapperClassName={styles["menu-wrapper"]}
            className={styles.menu}
          />
        </Fade>
      </div>
    </>
  );
}
