export function sendMessage(type, content = undefined) {
  if (!window.isNative) {
    window.postMessage({ type, content }, "*");
  } else {
    window.ReactNativeWebView.postMessage(JSON.stringify({ type, content }));
  }
}

export function addListener(type, callback) {
  window.addEventListener("message", event => {
    if (event.source !== window || event.data.type !== type) return;
    callback(event.data.content);
  });
}

export function removeListener(type, callback) {
  window.removeEventListener(type, callback);
}
