import React, { useState, useEffect } from "react";
import Modal from "./modal";

import Button from "./button";
import Loading from "./loading";
import VariantInfo from "./variant-info";
import WebOptions from "./web-options";
import { useCatalogFilter } from "../state/catalog-filter";
import { useConfiguration } from "../state/configuration";
import { getCheckoutLink } from "../utils/checkout-api";
import styles from "./buy-button.module.css";

export default function BuyButton({ product, variant, style }) {
  let [isModalOpen, setIsModalOpen] = useState(false);
  let [errorMessage, setErrorMessage] = useState("");
  let [checkoutUrl, setCheckoutUrl] = useState(null);

  let { filteredCatalog } = useCatalogFilter();
  useEffect(() => {
    closeModal();
  }, [filteredCatalog]);

  let { isIdle, configData } = useConfiguration();
  useEffect(() => {
    if (isModalOpen && isIdle) {
      closeModal();
    }
  }, [isModalOpen, isIdle]);

  const openModal = () => {
    setIsModalOpen(true);
    setErrorMessage("");

    getCheckoutLink(variant.id)
      .then(webUrl => {
        if (webUrl.includes("coveredbyrugs.myshopify.com")) {
          webUrl = webUrl.replace(
            "coveredbyrugs.myshopify.com",
            "coveredbyrugs.com"
          );
        }
        setCheckoutUrl(webUrl);
      })
      .catch(error => {
        console.log(error);
        setErrorMessage(
          "Unable to create a checkout link. Please try again later."
        );
      });
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setCheckoutUrl(null);
    setErrorMessage("");
  };

  const variantPrice =
    configData?.msrpEnabled && variant?.compareAtPrice
      ? variant.compareAtPrice
      : variant?.price;

  return (
    product.onlineStoreUrl &&
    variant && (
      <>
        <Button
          className={styles.button}
          style={style}
          onClick={openModal}
          loggingLabel={"buy"}
          loggingValue={{ product: product.handle, variant: variant.size }}
        >
          Buy Now - {variantPrice}
        </Button>

        <Modal isOpen={isModalOpen} onRequestClose={closeModal}>
          <div className={styles["modal-content"]}>
            {!checkoutUrl ? (
              !errorMessage ? (
                <Loading />
              ) : (
                <div className={styles["error-message"]}>{errorMessage}</div>
              )
            ) : (
              <div className={styles.menu}>
                <VariantInfo product={product} variant={variant} />

                <div className={styles.prompt}>
                  <h1 className={styles["prompt-header"]}>
                    Continue the checkout from your device!
                  </h1>

                  <WebOptions
                    url={checkoutUrl}
                    smsMessage={`Here is the purchase link you requested for the ${product.title}: ${checkoutUrl}`}
                    emailSubject={"Your requested rug purchase link"}
                    emailMessage={
                      `<p>The purchase link you requested for the ${product.title} can be found here:</p>` +
                      `<a href=${checkoutUrl}>${checkoutUrl}</a>`
                    }
                    qrCodePrompt={
                      "Use the camera app on your phone and scan the code for a checkout link."
                    }
                  />
                </div>
              </div>
            )}
          </div>
        </Modal>
      </>
    )
  );
}
