const serviceUrl = "https://rug-kiosk-service.azurewebsites.net";

export function getConfig(kioskId, dealerName) {
  const authStr = btoa(`${kioskId}:${dealerName}`);
  return fetch(serviceUrl, {
    method: "GET",
    headers: {
      Authorization: `Basic ${authStr}`,
      "Cache-Control": "no-cache"
    }
  })
    .catch(error => {
      console.log(error);
      return Promise.reject(
        "Unable to verify. Please check your internet connectivity or try again later."
      );
    })
    .then(res => {
      if (res.status === 200) {
        return res.json();
      } else {
        return Promise.reject(
          "Unable to verify. Check that the configuration is correct."
        );
      }
    })
    .then(data => {
      const config = { auth: authStr, data };
      return config;
    });
}

function parseConfig() {
  return JSON.parse(atob(window.localStorage.getItem("config")));
}

export function getKiosks(dealerId) {
  return fetch(`${serviceUrl}/kiosks/${dealerId}`, {
    headers: { "Cache-Control": "no-cache" }
  })
    .catch(error => {
      console.log(error);
      return Promise.reject(
        "Unable to connect to the server. " +
          "Please check your internet connectivity or try again later."
      );
    })
    .then(res => {
      if (res.status === 200) {
        return res.json();
      }
      console.log(res);
      return Promise.reject("Invalid customer number.");
    });
}

function postMessage(type, body) {
  let config = parseConfig();
  return fetch(`${serviceUrl}/${type}`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${config.auth}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(body)
  });
}

export function sendSms(phoneNum, message) {
  return postMessage("sms", {
    to_phone: phoneNum,
    content: message
  });
}

export function sendMail(toAddr, subject, htmlContent, images = null) {
  let body = {
    to_addr: toAddr,
    subject,
    html_content: htmlContent
  };

  if (!!images) {
    body["images"] = images;
  }

  return postMessage("email", body);
}

async function requestLoggingResourceToken() {
  let config = parseConfig();
  if (process.env.NODE_ENV === "development") {
    console.log("Requesting logging token...");
  }
  let response = await fetch(`${serviceUrl}/permission/logging`, {
    headers: {
      Authorization: `Basic ${config.auth}`,
      "Cache-Control": "no-cache"
    }
  });

  if (response.status === 200) {
    return response.json();
  } else {
    throw Error("Bad permission request");
  }
}

// Cache the token and the time it was requested
let loggingResourceToken = { timestamp: null, value: null };

export async function getLoggingResourceToken(noCache = false) {
  let now = performance.now();
  let ts = loggingResourceToken.timestamp;

  if (
    noCache ||
    !ts ||
    now - ts >= 30 * 60 * 1000 // get a new one after 30 minutes
  ) {
    try {
      const token = await requestLoggingResourceToken();
      loggingResourceToken = { timestamp: now, value: token };
      return loggingResourceToken.value;
    } catch (error) {
      console.error(error);
      loggingResourceToken = { timestamp: now, value: null };
      return loggingResourceToken.value;
    }
  } else {
    return loggingResourceToken.value;
  }
}
