export function compareVariantSizes(a, b) {
  const getFeet = dim => {
    if (dim === undefined) return NaN;

    const feet = parseInt(dim.split(" ", 2)[0]);
    const inches = parseInt(dim.split(" ", 2)[1] || 0);
    return feet + inches / 12;
  };

  const getArea = size => {
    const dim1 = size.split("x", 2)[0];
    const dim2 = size.split("x", 2)[1];
    return (getFeet(dim1) || 1) * (getFeet(dim2) || 1);
  };

  let _a = getArea(a.size);
  let _b = getArea(b.size);

  return _a < _b ? -1 : 1;
}
