import React, {
  useRef,
  forwardRef,
  useImperativeHandle,
  useState
} from "react";
import { AutoSizer } from "react-virtualized";

import Button from "./button";
import styles from "./signature-box.module.css";

const SignatureBox = forwardRef(({ className = "", style = {} }, ref) => {
  const canvasRef = useRef(null);

  useImperativeHandle(
    ref,
    () => ({
      getImage: () => {
        // fix black background in jpeg images
        const ctx = canvasRef.current.getContext("2d");
        // change compositing type
        ctx.globalCompositeOperation = "destination-over";
        ctx.fillStyle = "white";
        ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
        // change compositing back to the default
        ctx.globalCompositeOperation = "source-over";

        let imageData = canvasRef.current.toDataURL("image/jpeg");

        return imageData;
      }
    }),
    []
  );

  const [position, setPosition] = useState({ x: null, y: null });
  const [isDrawing, setIsDrawing] = useState(false);

  const getPosition = e => {
    const bounds = canvasRef.current.getBoundingClientRect();

    if (e.touches && e.touches.length > 0) {
      return {
        x: e.touches[0].clientX - bounds.left,
        y: e.touches[0].clientY - bounds.top
      };
    } else {
      return {
        x: e.clientX - bounds.left,
        y: e.clientY - bounds.top
      };
    }
  };

  const drawLine = (x1, y1, x2, y2) => {
    const scale = window.devicePixelRatio;
    const ctx = canvasRef.current.getContext("2d");
    ctx.beginPath();
    ctx.strokeStyle = "black";
    ctx.lineCap = "round";
    ctx.lineWidth = Math.ceil((window.innerWidth * scale) / 500);
    ctx.moveTo(Math.floor(x1 * scale), Math.floor(y1 * scale));
    ctx.lineTo(Math.floor(x2 * scale), Math.floor(y2 * scale));
    ctx.stroke();
    ctx.closePath();
  };

  const startDrawing = e => {
    if (!isDrawing) {
      const position = getPosition(e);
      // draw a "dot"
      drawLine(position.x, position.y, position.x + 1, position.y + 1);
      setPosition(position);
      setIsDrawing(true);
    }
  };

  const draw = e => {
    if (isDrawing === true) {
      const newPosition = getPosition(e);
      drawLine(position.x, position.y, newPosition.x, newPosition.y);
      setPosition(newPosition);
    }
  };

  const stopDrawing = e => {
    if (isDrawing === true) {
      drawLine(getPosition(e));
      setPosition({ x: null, y: null });
      setIsDrawing(false);
    }
  };

  const clear = () => {
    setIsDrawing(false);
    const ctx = canvasRef.current.getContext("2d");
    ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
  };

  const handleLoad = () => {
    const scale = window.devicePixelRatio;
    canvasRef.current.getContext("2d").scale(scale, scale);
  };

  return (
    <div className={`${styles.wrapper} ${className}`} style={style}>
      <AutoSizer>
        {({ width, height }) => (
          <canvas
            ref={canvasRef}
            style={{ width: `${width}px`, height: `${height}px` }}
            width={Math.floor(width * window.devicePixelRatio)}
            height={Math.floor(height * window.devicePixelRatio)}
            onMouseDown={startDrawing}
            onTouchStart={startDrawing}
            onMouseMove={draw}
            onTouchMove={draw}
            onMouseUp={stopDrawing}
            onTouchEnd={stopDrawing}
            onLoad={handleLoad}
          ></canvas>
        )}
      </AutoSizer>
      <div className={styles.title}>Signature</div>
      <Button inverted className={styles.clear} onClick={clear}>
        Clear
      </Button>
    </div>
  );
});

export default SignatureBox;
