import React, { useState, useEffect, useRef } from "react";

import { MdGesture } from "react-icons/md";

import Button from "./button";
import VariantInfo from "./variant-info";
import RugPadSelector from "./rug-pad-selector";
import SignatureBox from "./signature-box";
import EmailButton from "./email-button";

import { useConfiguration } from "../state/configuration";

import styles from "./info-menu.module.css";

export default function InfoMenu({
  product,
  variant,
  customImage,
  extraVariantText,
  pricingEnabled
}) {
  const { configData } = useConfiguration();
  const [rugPad, setRugPad] = useState(null);
  const [rugPadVariant, setRugPadVariant] = useState(null);

  const showAvailableQuantity = configData?.availableQuantityEnabled;

  const msrpEnabled = configData?.msrpEnabled;
  const variantPrice = getPrice(variant, msrpEnabled);
  const rugPadVariantPrice = getPrice(rugPadVariant, msrpEnabled);

  const total = totalPrice(variantPrice, rugPadVariantPrice);

  let [signatureActive, setSignatureActive] = useState(false);
  const sigRef = useRef(null);
  const prepareAttachments = () => {
    if (sigRef && sigRef.current) {
      return [
        {
          filename: "signature.jpg",
          cid: "signature",
          data: sigRef.current.getImage()
        }
      ];
    } else {
      return null;
    }
  };

  useEffect(() => {
    return () => setSignatureActive(false);
  }, []);

  // Email form
  const [includeDealerEmail] = useState(true);
  const dealerEmail = configData.emailCc;
  const [error, setError] = useState("");

  return (
    <div className={styles.content}>
      <div className={styles["variant-wrapper"]}>
        <VariantInfo
          product={product}
          variant={variant}
          customImage={customImage}
          extraVariantText={extraVariantText}
          showSku={false}
          showAvailableQuantity={showAvailableQuantity}
        />
      </div>

      <div className={styles.pricing}>
        <h1 className={styles.prompt}>Draft Order:</h1>

        <div className={styles["item-grid"]}>
          {/* Product row */}
          <div className={styles.product}>
            <div>
              <b>{product.title}</b>
            </div>
            {extraVariantText ? (
              <>
                <div>
                  {variant.size}
                  {extraVariantText}
                </div>
                <div>{variant.sku}</div>
              </>
            ) : (
              <div>
                {variant.size} ({variant.sku})
              </div>
            )}
          </div>
          {pricingEnabled ? (
            <div className={styles.price}>{variantPrice}</div>
          ) : (
            <div></div>
          )}

          {/* Rug pad row */}
          {product.productType !== "Rug Pad" && (
            <>
              <RugPadSelector
                onPadSelected={setRugPad}
                onVariantSelected={setRugPadVariant}
              />
              {pricingEnabled ? (
                <div className={styles.price}>
                  {rugPadVariant ? rugPadVariantPrice : "$0.00"}
                </div>
              ) : (
                <div></div>
              )}
            </>
          )}

          {/* Totals row */}
          {pricingEnabled && (
            <>
              <div className={styles.total}>Total:</div>
              <div className={`${styles.price} ${styles.total}`}>{total}</div>
            </>
          )}
        </div>

        <div className={styles.buttons}>
          {!pricingEnabled ? null : !signatureActive ? (
            <Button onClick={() => setSignatureActive(true)}>
              <MdGesture className={styles.icon} /> Signature (Optional)
            </Button>
          ) : (
            <SignatureBox ref={sigRef} />
          )}

          <EmailButton
            style={{ width: "100%" }}
            subject={"Draft Order"}
            message={createEmailHtml(
              product,
              variant,
              customImage,
              extraVariantText,
              rugPad,
              rugPadVariant,
              pricingEnabled,
              msrpEnabled,
              total,
              signatureActive
            )}
            extraRecipients={includeDealerEmail ? [dealerEmail] : []}
            getImageAttachments={signatureActive ? prepareAttachments : null}
            keepActive={true}
            onSuccess={() => setSignatureActive(false)}
            onError={setError}
            loggingLabel={
              !extraVariantText ? "draft order" : "custom rug draft order"
            }
            loggingValue={{
              product: product.handle,
              variant: !extraVariantText
                ? variant.size
                : variant.size + extraVariantText,
              signature: signatureActive
            }}
          />
        </div>

        {error && <div style={{ marginTop: "1em" }}>{error}</div>}

        {/* {includeDealerEmail && dealerEmail && (
          <Chip
            style={{ marginTop: "1em" }}
            label={dealerEmail}
            onClick={() => setIncludeDealerEmail(false)}
          />
        )} */}
      </div>
    </div>
  );
}

function getPrice(variant, msrpEnabled) {
  return msrpEnabled && variant?.compareAtPrice
    ? variant.compareAtPrice
    : variant?.price;
}

function totalPrice(variantPrice, rugPadVariantPrice) {
  let _total = 0;

  if (variantPrice) {
    _total += parseFloat(variantPrice.replace(/[$,]/g, ""));
  }

  if (rugPadVariantPrice) {
    _total += parseFloat(rugPadVariantPrice.replace(/[$,]/g, ""));
  }

  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD"
  }).format(_total);
}

function createEmailHtml(
  product,
  variant,
  customImage,
  extraVariantText,
  rugPad,
  rugPadVariant,
  pricingEnabled,
  msrpEnabled,
  total,
  includeSig = false
) {
  const variantPrice = getPrice(variant, msrpEnabled);
  const rugPadVariantPrice = getPrice(rugPadVariant, msrpEnabled);

  const rugPadHtml =
    rugPad && rugPadVariant
      ? `
        <tr>
          <td style="padding: 10px 0;">
            <b>${rugPad.title}<br/>${rugPadVariant.size}</b>
            <br/>${rugPadVariant.sku}</td>
          <td style="padding: 10px 0; text-align: right;">${
            pricingEnabled ? rugPadVariantPrice : ""
          }</td>
        </tr>
      `
      : "";

  const totalHtml = pricingEnabled
    ? `
      <tr style="border-top: 1px solid black;">
        <td style="padding: 10px 0;">Total</td>
        <td style="padding: 10px 0; text-align: right;">${total}</td>
      </tr>
    `
    : "";

  const signatureHtml = includeSig
    ? `
      <tr>
        <td align="left" style="font-size:0px;padding:10px 25px;word-break:break-word;">
          <div style="font-family:Ubuntu, Helvetica, Arial, sans-serif;font-size:13px;line-height:1;text-align:left;color:#000000;">Signature:</div>
        </td>
      </tr>
      <tr>
        <td align="center" style="font-size:0px;padding:10px 25px;word-break:break-word;">
          <table border="0" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;border-spacing:0px;">
            <tbody>
              <tr>
                <td style="width:300px;"> <img alt="Signature" height="auto" src="cid:signature" style="border:0;display:block;outline:none;text-decoration:none;height:auto;width:100%;font-size:13px;" width="300" /> </td>
              </tr>
            </tbody>
          </table>
        </td>
      </tr>
    `
    : "";

  const emailHtml = emailTemplate
    .replace("IMAGE_ALT", product.title)
    .replace(
      "IMAGE_SRC",
      extraVariantText ? customImage.originalSrc : variant.image.originalSrc
    )
    .replace("PRODUCT_TITLE", product.title)
    .replace("VARIANT_SIZE", variant.size)
    .replace("VARIANT_EXTRA_TEXT", extraVariantText ?? "")
    .replace("VARIANT_SKU", variant.sku)
    .replace("VARIANT_PRICE", pricingEnabled ? variantPrice : "")
    .replace("RUG_PAD", rugPadHtml)
    .replace("ORDER_TOTAL", totalHtml)
    .replace("SIGNATURE_ATTACHMENT", signatureHtml);

  return emailHtml;
}

