import React, { useEffect } from "react";

import Fade from "../animations/fade";
import { useKeyboard } from "../state/keyboard";
import { useCatalog } from "../state/catalog";
import { useCatalogFilter } from "../state/catalog-filter";
import ConfigButton from "../components/config-button";
import styles from "./collection-filter-picker.module.css";

import { logEvent } from "../utils/logging";

export default function CollectionFilterPicker() {
  let { catalog } = useCatalog();
  let {
    collectionFilters,
    activeCollection,
    setActiveCollection
  } = useCatalogFilter();

  const show = catalog.length > 0 && activeCollection === null;

  const { setIsActive } = useKeyboard();
  useEffect(() => {
    if (show) {
      setIsActive(false);
    }
  }, [show, setIsActive]);

  const handleClick = (e, collection) => {
    setActiveCollection(collection);
    logEvent(
      "click",
      "button",
      "category picker",
      collection.label,
      e.timeStamp,
      e.clientX,
      e.clientY
    );
  };

  return (
    <Fade className={styles.overlay} in={show} duration={500}>
      <h1 className={styles.prompt}>Pick a category to browse:</h1>

      <div className={styles.collections}>
        {collectionFilters.map((collection, i) => (
          <div
            key={i}
            // Fixes white border issue on iOS. Removes box-shadow, though.
            style={
              window.isNative 
              ? { WebkitMaskImage: "linear-gradient(white, black)" } 
              : undefined
            }
            className={styles.collection}
            onClick={e => handleClick(e, collection)}
          >
            <img alt={collection.value} src={collection.path} />
            <div className={styles.label}>
              <div className={styles.text}>
                {collection.label || collection.value}
              </div>
            </div>
          </div>
        ))}
      </div>

      {window.isNative && (
        <ConfigButton
          style={{
            position: "absolute",
            bottom: "1rem",
            left: "1rem"
          }}
        />
      )}
    </Fade>
  );
}
