import React from "react";

import Fade from "../animations/fade";
import { useConfiguration } from "../state/configuration";
import styles from "./screensaver.module.css";

export default function Screensaver() {
  let { configData, isIdle } = useConfiguration();

  let videoSrc = configData.videos[0].path;

  return (
    <Fade
      className={styles.screensaver}
      in={isIdle && !window.isNative}
      duration={500}
    >
      <video className={styles.video} loop autoPlay>
        <source src={videoSrc} type="video/mp4" />
        This video format is not supported
      </video>
      <div className={styles.overlay}>
        <div className={styles.ripple} />
        <div className={styles.text}>
          Browse hundreds of products. <br /> Tap anywhere to begin.
        </div>
      </div>
    </Fade>
  );
}
