import React, { useState, useContext, useEffect } from "react";

import { useCatalogFilter } from "./catalog-filter";
import { useConfiguration } from "./configuration";
import { compareVariantSizes } from "../utils/compare";

const context = React.createContext({
  selectedProduct: null,
  setSelectedProduct: product => {},
  selectedVariant: null,
  setSelectedVariant: (variant, shouldFocusVariant = false) => {},
  shouldFocusVariant: false
});

export const useSelectedProduct = () => useContext(context);

export function SelectedProductProvider({ children }) {
  let [selectedProduct, setSelectedProduct] = useState(null);
  let [selectedVariant, setSelectedVariant] = useState(null);
  let [shouldFocusVariant, setShouldFocusVariant] = useState(false);
  let { filteredCatalog, activeFilters } = useCatalogFilter();
  let { configData, isIdle } = useConfiguration();

  useEffect(() => {
    if (filteredCatalog.length > 0) {
      setSelectedProduct(filteredCatalog[0]);
    } else {
      setSelectedProduct(null);
    }
  }, [filteredCatalog, activeFilters]);

  useEffect(() => {
    if (filteredCatalog.length > 0 && isIdle) {
      setSelectedProduct(filteredCatalog[0]);
    }
  }, [filteredCatalog, isIdle]);

  useEffect(() => {
    if (selectedProduct && selectedProduct.variants.length > 0) {
      // sort from largest to smallest
      let sortedVariants = selectedProduct.variants
        .slice()
        .sort(compareVariantSizes)
        .reverse();

      let firstAvailable;
      if (configData.buyEnabled) {
        // set default to the first largest in stock
        firstAvailable =
          sortedVariants.find(variant => variant.availableForSale) ||
          sortedVariants[0];
      } else {
        firstAvailable = sortedVariants[0];
      }

      if (firstAvailable) {
        _setSelectedVariant(firstAvailable, false);
      }
    }
  }, [configData, selectedProduct]);

  const _setSelectedVariant = (variant, shouldFocusVariant = false) => {
    setSelectedVariant(variant);
    setShouldFocusVariant(shouldFocusVariant);
  };

  let productContext = {
    selectedProduct,
    setSelectedProduct,
    selectedVariant,
    setSelectedVariant: _setSelectedVariant,
    shouldFocusVariant
  };

  return <context.Provider value={productContext}>{children}</context.Provider>;
}
