import React, { useState, useEffect } from "react";
import Dropdown from "./dropdown";
import Fade from "../animations/fade";
import { useCatalog } from "../state/catalog";

import styles from "./rug-pad-selector.module.css";

export default function RugPadSelector({
  onPadSelected = () => {},
  onVariantSelected = () => {}
}) {
  const [pads, setPads] = useState(null);
  const [variants, setVariants] = useState([]);
  const [selectedPad, setSelectedPad] = useState(null);
  const [selectedVariant, setSelectedVariant] = useState(null);

  // populate pad types
  let { catalog } = useCatalog();
  useEffect(() => {
    if (catalog && catalog.length > 0) {
      const _pads = catalog
        .filter(p => p.productType === "Rug Pad")
        .map(p => {
          return { label: p.title, value: p };
        });

      setPads(_pads);
    }
  }, [catalog]);

  // populate variants for the selected pad
  useEffect(() => {
    if (selectedPad !== null) {
      let pad = selectedPad.value;
      let _variants = pad.variants.map(v => {
        return { label: `${v.size} (${v.sku})`, value: v };
      });

      setVariants(_variants);
      setSelectedVariant(_variants[0]);
    } else {
      setVariants([]);
      setSelectedVariant(null);
    }
  }, [selectedPad]);

  useEffect(() => {
    onPadSelected(selectedPad ? selectedPad.value : null);
  }, [selectedPad, onPadSelected]);

  useEffect(() => {
    onVariantSelected(selectedVariant ? selectedVariant.value : null);
  }, [selectedVariant, onVariantSelected]);

  return (
    pads && (
      <div className={styles.wrapper}>
        <Dropdown
          alt={false}
          inverted
          triggerClass={styles.selector}
          triggerStyle={{ fontWeight: "bold" }}
          defaultItemLabel="No rug pad"
          selectedItem={selectedPad}
          items={pads}
          onChange={selectedItem => {
            setSelectedPad(selectedItem);
          }}
        />

        <Fade
          style={{ width: "100%" }}
          in={variants !== null && selectedVariant !== null}
        >
          <Dropdown
            alt={false}
            inverted
            triggerClass={styles.selector}
            selectedItem={selectedVariant}
            items={variants}
            onChange={selectedItem => setSelectedVariant(selectedItem)}
          />
        </Fade>
      </div>
    )
  );
}
