function createCheckout(variantId) {
  const url = "https://coveredbyrugs.myshopify.com/api/2019-07/graphql.json";

  const checkoutQuery = `
    mutation {
      checkoutCreate(input: {
        lineItems: [{ variantId: "${variantId}", quantity: 1 }]
      }) {
        checkout {
          webUrl
        }
      }
    }
  `;

  return fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/graphql",
      "X-Shopify-Storefront-Access-Token": "52d0b261fd630742e4c65c5b0e69e24c"
    },
    body: checkoutQuery
  });
}

export function getCheckoutLink(variantId) {
  return createCheckout(variantId)
    .then(res => res.json())
    .then(res => res.data.checkoutCreate.checkout.webUrl);
}
