import React from "react";

import Checkbox from "./checkbox";

export default function DropdownMultiselect({
  className = "",
  style = {},
  defaultItemLabel = "All",
  items = [
    { label: "Item 1", value: "item1" },
    { label: "Item 2", value: "item2" },
    {
      label: "Item 3 Item 3 Item 3 Item 3 Item 3 Item 3 Item 3 ",
      value: "item3"
    }
  ],
  selectedItems = [],
  availableItems = [],
  onChange = selectedItems => {}
}) {
  const isItemChecked = item => {
    return selectedItems.some(
      selectedItem => selectedItem.value === item.value
    );
  };
  const isItemDisabled = item => {
    return !availableItems.some(
      availableItem => availableItem.value === item.value
    );
  };
  const resetItems = () => onChange([]);
  const addItem = item => onChange([...selectedItems, item]);
  const removeItem = item =>
    onChange(selectedItems.filter(i => i.value !== item.value));

  const handleClick = item => {
    if (isItemChecked(item)) {
      removeItem(item);
    } else {
      addItem(item);
    }
  };

  return (
    <div className={`${className}`} style={style}>
      <Checkbox
        label={defaultItemLabel}
        isChecked={!selectedItems || selectedItems.length === 0}
        onClick={resetItems}
      />

      {items.map((item, i) => (
        <Checkbox
          style={{ marginTop: "0.5em" }}
          key={i}
          label={item.label}
          isChecked={isItemChecked(item)}
          isDisabled={isItemDisabled(item)}
          onClick={() => handleClick(item)}
        />
      ))}
    </div>
  );
}
