import React, { useState, useContext, useEffect, useCallback } from "react";

export const UPDATE_STATUS = {
  NOT_CHECKED: "not-checked",
  CHECKING: "checking",
  DOWNLOADING: "downloading",
  STAGED: "staged",
  COMPLETE: "complete",
  OFFLINE: "offline",
  ERROR: "error"
};

const context = React.createContext({
  updateStatus: { status: "", details: "" },
  changeStatus: (status, details) => {},
  lastUpdatedAt: null
});

export const useUpdateStatus = () => useContext(context);

export function UpdateStatusProvider({ children }) {
  let [updateStatus, setUpdateStatus] = useState({
    status: UPDATE_STATUS.NOT_CHECKED,
    details: !window.isNative ? "Updates may be available." : ""
  });
  let [lastUpdatedAt, setLastUpdatedAt] = useState(null);

  useEffect(() => {
    if (
      updateStatus.status === UPDATE_STATUS.STAGED ||
      updateStatus.status === UPDATE_STATUS.COMPLETE ||
      updateStatus.status === UPDATE_STATUS.OFFLINE ||
      updateStatus.status === UPDATE_STATUS.ERROR
    ) {
      setLastUpdatedAt(new Date().toLocaleString());
    }
  }, [updateStatus.status]);

  const changeStatus = useCallback(
    (status, details) => {
      setUpdateStatus({ status, details });
    },
    [setUpdateStatus]
  );

  return (
    <context.Provider value={{ updateStatus, changeStatus, lastUpdatedAt }}>
      {children}
    </context.Provider>
  );
}
