import React from "react";

import styles from "./button.module.css";

import { logEvent } from "../utils/logging";

export default function Button({
  className = "",
  style = {},
  alt = false,
  disabled = false,
  inverted = false,
  onClick = () => {},
  children,
  loggingLabel = null,
  loggingValue = null
}) {
  const handleClick = e => {
    onClick(e);

    if (loggingLabel !== null) {
      logEvent(
        "click",
        "button",
        loggingLabel,
        loggingValue,
        e.timeStamp,
        e.clientX,
        e.clientY
      );
    }
  };

  return (
    <div
      className={`
        ${!alt ? styles.button : styles["button-alt"]} 
        ${disabled ? styles.disabled : ""}
        ${inverted ? (!alt ? styles.inverted : styles["inverted-alt"]) : ""}
        ${className}
      `}
      style={style}
      onClick={handleClick}
    >
      {children}
    </div>
  );
}
