import React, { useState, useEffect, useRef } from "react";
import { CSSTransition } from "react-transition-group";

import Fade from "../animations/fade";
import styles from "./expandable.module.css";

export default function Expandable({
  className = "",
  style = {},
  children,
  minHeight,
  maxHeight,
  triggerText = "See more"
}) {
  let [expanded, setExpanded] = useState(false);
  let [showTrigger, setShowTrigger] = useState(true);

  let containerRef = useRef();
  useEffect(() => {
    if (containerRef && containerRef.current) {
      if (
        containerRef.current.offsetHeight >= containerRef.current.scrollHeight
      ) {
        setShowTrigger(false);
      } else {
        setShowTrigger(true);
      }
    }
  }, [children]);

  return (
    <CSSTransition
      in={expanded}
      timeout={250}
      classNames={{
        enter: styles["expanding"],
        enterDone: styles["expanded"]
      }}
    >
      <div
        ref={containerRef}
        className={`${styles["expandable"]} ${className}`}
        style={{ ...style, maxHeight: expanded ? maxHeight : minHeight }}
      >
        {children}

        {showTrigger && (
          <Fade in={!expanded} duration={250}>
            <div
              className={styles["overlay-trigger"]}
              onClick={() => setExpanded(true)}
            >
              <div className={styles["overlay-text"]}>{triggerText}</div>
            </div>
          </Fade>
        )}
      </div>
    </CSSTransition>
  );
}
