import React, { useState, useEffect } from "react";
import Modal from "./modal";

import Button from "./button";
import InfoMenu from "./info-menu";
import CustomRugsMenu from "./custom-rugs-menu";
import { useCatalogFilter } from "../state/catalog-filter";
import { useConfiguration } from "../state/configuration";
import styles from "./info-button.module.css";

export default function InfoButton({
  style,
  product,
  variant,
  customRugsEnabled = false
}) {
  let [isModalOpen, setIsModalOpen] = useState(false);

  const openModal = () => setIsModalOpen(true);
  const closeModal = () => {
    setIsModalOpen(false);
  };

  // close on filter change
  let { filteredCatalog } = useCatalogFilter();
  useEffect(() => {
    closeModal();
  }, [filteredCatalog]);

  // close on idle
  let { isIdle, configData } = useConfiguration();
  useEffect(() => {
    if (isModalOpen && isIdle) {
      closeModal();
    }
  }, [isModalOpen, isIdle]);

  const variantPrice =
    configData?.msrpEnabled && variant?.compareAtPrice
      ? variant.compareAtPrice
      : variant?.price;

  const pricingEnabled = configData.pricingEnabled && variantPrice;

  return (
    product &&
    variant && (
      <>
        <Button
          className={styles.button}
          style={style}
          onClick={openModal}
          loggingLabel={!customRugsEnabled ? "info" : "custom rug"}
          loggingValue={{ product: product.handle, variant: variant.size }}
        >
          {!customRugsEnabled ? (
            <>
              More Info
              {pricingEnabled && <> - {variantPrice}</>}
            </>
          ) : (
            <>Select Rug Finish</>
          )}
        </Button>

        <Modal isOpen={isModalOpen} onRequestClose={closeModal}>
          {!customRugsEnabled ? (
            <InfoMenu
              product={product}
              variant={variant}
              pricingEnabled={pricingEnabled}
            />
          ) : (
            <CustomRugsMenu
              product={product}
              variant={variant}
              pricingEnabled={pricingEnabled}
            />
          )}
        </Modal>
      </>
    )
  );
}
