import React, { useState, useEffect, useContext, useCallback } from "react";

import { useUpdateStatus, UPDATE_STATUS } from "./update-status";
import { useConfiguration } from "../state/configuration";
import { getAllProducts } from "../utils/products-api";
import {
  addListener,
  removeListener,
  sendMessage
} from "../utils/window-messaging";

const context = React.createContext({
  catalog: [],
  isUpdating: false,
  updateCatalog: () => {},
  hasDownloadConsent: !window.isNative,
  grantDownloadConsent: () => {}
});

export const useCatalog = () => useContext(context);

export function CatalogProvider({ children }) {
  // only allow updating after the initial catalog has been loaded
  let [canUpdate, setCanUpdate] = useState(false);
  // only download once consent is given (native only);
  let [hasDlConsent, setHasDlConsent] = useState(!window.isNative);
  let [isUpdating, setIsUpdating] = useState(false);
  let [stagedCatalog, setStagedCatalog] = useState([]);
  let [catalog, setCatalog] = useState([]);
  // some products may fail downloading
  let [estimatedSize, setEstimatedSize] = useState(0);

  // use the previous catalog on startup, if available
  usePreviousCatalog(setCatalog, setCanUpdate, setHasDlConsent);
  // schedules updates
  const timeBetweenUpdates = 30 * 60 * 1000;
  useUpdateScheduler(
    timeBetweenUpdates, 
    isUpdating, 
    setIsUpdating, 
    canUpdate,
    hasDlConsent
  );
  // update the catalog when isUpdating = true
  useUpdate(
    isUpdating,
    setIsUpdating,
    setEstimatedSize,
    catalog,
    setStagedCatalog
  );
  // wait until the kiosk is idling to apply, so that user interaction isn't interrupted
  useApplyOnIdle(
    stagedCatalog,
    setStagedCatalog,
    catalog,
    setCatalog,
    estimatedSize
  );

  const updateCatalog = useCallback(() => {
    if (!isUpdating) setIsUpdating(true);
  }, [isUpdating, setIsUpdating]);

  // Used by native to explicitly start downloading after user consent is granted
  const grantDownloadConsent = useCallback(() => {
    if (!hasDlConsent) setHasDlConsent(true);
  }, [hasDlConsent, setHasDlConsent]);

  let catalogContext = {
    catalog,
    isUpdating,
    updateCatalog,
    hasDownloadConsent: hasDlConsent,
    grantDownloadConsent
  };

  return (
    <context.Provider value={catalogContext}>
      {children}
    </context.Provider>
  );
}

function usePreviousCatalog(setCatalog, setCanUpdate, setHasDlConsent) {
  const { lastUpdatedAt } = useUpdateStatus();
  const { configData } = useConfiguration();

  useEffect(() => {
    if (lastUpdatedAt === null) {
      if (configData.products.url === "trial-products.json") {
        setCatalog(require("../native/trial-products.json"));
        setHasDlConsent(true);
        // setCanUpdate(true);
        return;
      }

      sendMessage("REQ_OLD_PRODUCT_DATA");

      const loadPrevious = products => {
        setCatalog(products);
        setCanUpdate(true);
        if (window.isNative && products.length > 0) {
          setHasDlConsent(true);
        }
      };

      addListener("RESP_OLD_PRODUCT_DATA", loadPrevious);
      return () => removeListener("RESP_OLD_PRODUCT_DATA", loadPrevious);
    }
  }, [lastUpdatedAt, configData, setCatalog, setCanUpdate, setHasDlConsent]);
}

function useUpdateScheduler(
  timeBetweenUpdates,
  isUpdating,
  setIsUpdating,
  canUpdate,
  hasDlConsent
) {
  const { lastUpdatedAt } = useUpdateStatus();

  useEffect(() => {
    if (!isUpdating && canUpdate && hasDlConsent) {
      if (lastUpdatedAt === null) {
        setIsUpdating(true);
      } else {
        let timer = setInterval(() => {
          let timeSinceUpdate = new Date() - new Date(lastUpdatedAt);
          if (timeSinceUpdate >= timeBetweenUpdates) {
            setIsUpdating(true);
          }
        }, 15 * 1000);

        return () => clearInterval(timer);
      }
    }
  }, [lastUpdatedAt, timeBetweenUpdates, isUpdating, setIsUpdating, canUpdate, hasDlConsent]);
}

function useUpdate(
  isUpdating,
  setIsUpdating,
  setEstimatedSize,
  catalog,
  setStagedCatalog
) {
  let { changeStatus } = useUpdateStatus();

  useEffect(() => {
    if (isUpdating) {
      changeStatus(UPDATE_STATUS.CHECKING, "Checking for updates...");
      // retrieve new product data from an API
      getAllProducts()
        .then(products => {
          if (process.env.NODE_ENV === "development") {
            console.log("Downloaded product data:", products);
          }
          setEstimatedSize(products.length);
          sendMessage("START_DOWNLOADING_ASSETS", products);
        })
        .catch(error => handleError(error));

      // Throttle changeStatus to once every second, since it
      // can block the UI if called too frequently.
      // https://github.com/facebook/react/issues/14110#issuecomment-448074060
      let lastProgressUpdate = null;
      const handleProgress = ({ progress, total }) => {
        const now = performance.now();
        if (lastProgressUpdate === null || now - lastProgressUpdate >= 1000) {
          lastProgressUpdate = now;
          changeStatus(
            UPDATE_STATUS.DOWNLOADING,
            `Downloading products (${progress}/${total})...`
          );
        }
      };

      const handleError = error => {
        window.navigator.onLine
          ? changeStatus(UPDATE_STATUS.ERROR, error)
          : changeStatus(
              UPDATE_STATUS.OFFLINE,
              "Offline; unable to update the catalog."
            );
        setIsUpdating(false);
      };

      const handleComplete = products => {
        const msg = window.isNative
          ? 'Update available. Press "Apply Catalog Updates" to apply changes.'
          : "Update available. Waiting for the next idle state to apply changes.";
        changeStatus(UPDATE_STATUS.STAGED, msg);

        if (JSON.stringify(catalog) === JSON.stringify(products)) {
          // There's been no changes; skip staging and applying
          sendMessage("CLEANUP_ASSETS");
          changeStatus(UPDATE_STATUS.COMPLETE, "The catalog is up-to-date.");
        } else {
          setStagedCatalog(products);
        }
        setIsUpdating(false);
      };

      addListener("DOWNLOADING_ASSETS", handleProgress);
      addListener("ERROR_DOWNLOADING_ASSETS", handleError);
      addListener("FINISHED_DOWNLOADING_ASSETS", handleComplete);

      return () => {
        removeListener("DOWNLOADING_ASSETS", handleProgress);
        removeListener("ERROR_DOWNLOADING_ASSETS", handleError);
        removeListener("FINISHED_DOWNLOADING_ASSETS", handleComplete);
      };
    }
  }, [
    changeStatus,
    isUpdating,
    setIsUpdating,
    setEstimatedSize,
    catalog,
    setStagedCatalog
  ]);
}

function useApplyOnIdle(
  stagedCatalog,
  setStagedCatalog,
  catalog,
  setCatalog,
  estimatedSize
) {
  let { isIdle, setIsIdle } = useConfiguration();
  let { changeStatus } = useUpdateStatus();
  const { configData } = useConfiguration();

  useEffect(() => {
    const isTrial = window.isNative && configData.products.url === "trial-products.json";

    if (stagedCatalog.length > 0 && (isIdle || catalog.length === 0 || isTrial)) {
      const apply = () => {
        if (process.env.NODE_ENV === "development") {
          console.log("Staged catalog applied:", stagedCatalog);
        }
        // This should be the only place setCatalog is called (after usePreviousCatalog).
        // Otherwise there is a risk of two updates happening concurrently
        // in useUpdate, where catalog is a dependency.
        setCatalog(stagedCatalog);
        setStagedCatalog([]);
        sendMessage("CLEANUP_ASSETS");
        if (stagedCatalog.length < estimatedSize) {
          let missing = estimatedSize - stagedCatalog.length;
          changeStatus(
            UPDATE_STATUS.COMPLETE,
            `The catalog was updated, but ${missing} products could not be downloaded.`
          );
        } else {
          changeStatus(UPDATE_STATUS.COMPLETE, "The catalog is up-to-date.");
        }
      };

      if (window.isNative) {
        apply();
        // Native needs to explicity reset isIdle to false since it does not use
        // the screensaver.
        setIsIdle(false);
      } else {
        // wait for idle state to apply
        // add a delay to prevent fps drops when going idle
        let delay = setTimeout(apply, 1000);

        return () => clearTimeout(delay);
      }
    }
  }, [
    configData,
    isIdle,
    setIsIdle,
    changeStatus,
    stagedCatalog,
    setStagedCatalog,
    catalog,
    setCatalog,
    estimatedSize
  ]);
}
