import React from "react";

import Button from "./button";
import styles from "./kiosk-card.module.css";

export default function KioskCard({
  className = "",
  style = {},
  inverted = false,
  kiosk = { number: null, location: null, info: null },
  onClick = () => {}
}) {
  let { address, city, state, zip } = kiosk.location;

  return (
    <Button
      alt
      inverted={inverted}
      className={`${styles.wrapper} ${className ? className : ""}`}
      style={style}
      onClick={onClick}
    >
      <div className={styles.content}>
        <div className={styles.number}>
          <span>#{kiosk.number}</span>
        </div>
        <div
          className={`${styles.divider} ${inverted ? styles.inverted : ""}`}
        />
        <div className={styles.location}>
          <p>{address}</p>
          <p>
            {city}, {state} {zip}
          </p>
        </div>
      </div>

      {kiosk.info && (
        <div className={styles.info}>
          <p>{kiosk.info}</p>
        </div>
      )}
    </Button>
  );
}
