import React, { useState } from "react";
import { MdSettings } from "react-icons/md";
import { FaCircle } from "react-icons/fa";

import Button from "./button";
import ConfigModal from "./config-modal";
import { useUpdateStatus, UPDATE_STATUS } from "../state/update-status";

import styles from "./config-button.module.css";

export default function ConfigButton({ style, className }) {
  const [isOpen, setIsOpen] = useState(false);
  const { updateStatus } = useUpdateStatus();

  return (
    <>
      <Button
        style={style}
        className={className}
        onClick={() => setIsOpen(true)}
      >
        <MdSettings className={styles.icon} />
        {updateStatus && updateStatus.status === UPDATE_STATUS.STAGED && (
          <FaCircle className={styles.notification} />
        )}
      </Button>

      <ConfigModal isOpen={isOpen} onRequestClose={() => setIsOpen(false)} />
    </>
  );
}
