import React, { useState } from "react";
import ReactDOM from "react-dom";

import ElectronUpdateStatus from "./components/electron-update-status";

import { KeyboardProvider } from "./state/keyboard";
import { ConfigurationProvider } from "./state/configuration";
import { UpdateStatusProvider } from "./state/update-status";
import { CatalogProvider } from "./state/catalog";
import { CatalogFilterProvider } from "./state/catalog-filter";
import { SelectedProductProvider } from "./state/selected-product";
import { fetchProxy } from "./utils/fetch-proxy";

import App from "./app";
import "./keyboard.css";
import "./index.css";

window.isNative = !!window.ReactNativeWebView;
if (window.isNative) {
  window.fetch = fetchProxy;
}

const AppRenderer = () => {
  // Do not trigger electron updates for the iOS app.
  const shouldNotUpdate = window.isNative;
  // Note that `shouldNotUpdate` must be declared. If process.env
  // is wrapped in `useState`, it will not be evaluated properly at build-time.
  const [isAppUpdated, setIsAppUpdated] = useState(shouldNotUpdate);

  // If running the desktop version, make sure the app is updated
  // before loading the UI.
  return !isAppUpdated ? (
    <ElectronUpdateStatus onUpdated={() => setIsAppUpdated(true)} />
  ) : (
    <KeyboardProvider>
      <ConfigurationProvider>
        <UpdateStatusProvider>
          <CatalogProvider>
            <CatalogFilterProvider>
              <SelectedProductProvider>
                <App />
              </SelectedProductProvider>
            </CatalogFilterProvider>
          </CatalogProvider>
        </UpdateStatusProvider>
      </ConfigurationProvider>
    </KeyboardProvider>
  );
};

ReactDOM.render(<AppRenderer />, document.getElementById("root"));
