import { sendMessage, addListener, removeListener } from "./window-messaging";

export function fetchProxy() {
  return new Promise((resolve, reject) => {
    let rand = Math.floor(Math.random() * 100000).toString();

    const handleResponse = result => {
      console.warn(result);
      removeListener(`FETCH_RESPONSE_${rand}`, handleResponse);

      let { response, error } = result;
      if (error) {
        reject(error);
      } else {
        // This comes in as plain JSON, not a proper Request,
        // so we fake a json() method
        response.json = () => Promise.resolve(response._json);
        resolve(response);
      }
    };

    addListener(`FETCH_RESPONSE_${rand}`, handleResponse);
    sendMessage(`FETCH_REQUEST_${rand}`, [...arguments]);
  });
}
