import React, { useState, useEffect } from "react";
import { MdExitToApp } from "react-icons/md";

import Modal from "./modal";
import Button from "./button";
import Input from "./input";
import KioskCard from "./kiosk-card";
import { useCatalog } from "../state/catalog";
import { useUpdateStatus, UPDATE_STATUS } from "../state/update-status";
import { useConfiguration } from "../state/configuration";

import thirdPartyNotice from "../assets/thirdpartynotice";
import styles from "./config-modal.module.css";

import { version } from "../../package.json";

export default function ConfigModal({
  isOpen = false,
  onRequestClose = () => {}
}) {
  let { catalog } = useCatalog();
  let { configData, isIdle, setIsIdle, logout } = useConfiguration();
  let [isNoticeOpen, setIsNoticeOpen] = useState(false);
  let [logoutPressed, setLogoutPressed] = useState(false);
  let [passcode, setPasscode] = useState("");
  let [errorMessage, setErrorMessage] = useState("");

  useEffect(() => {
    if (isOpen) {
      setIsNoticeOpen(false);
      setLogoutPressed(false);
      setPasscode("");
    }
  }, [isOpen]);

  useEffect(() => {
    if (isIdle) {
      onRequestClose();
    }
  }, [isIdle, onRequestClose]);

  let { updateStatus, lastUpdatedAt } = useUpdateStatus();

  const onIdleClick = e => {
    // Prevent the user interaction timer from capturing this click,
    // or else isIdle will be set back to false immediately.
    e.stopPropagation();
    setIsIdle(true);
  };

  const onDisclaimerClick = () => setIsNoticeOpen(true);

  const onLogoutClick = () => {
    setLogoutPressed(true);
    if (window.isNative) {
      logout();
    }
  };

  const handleCodeChange = e => {
    setErrorMessage("");
    let code = e.target.value;
    code = code.slice(0, 30);
    setPasscode(code);
  };

  const handleCodeSubmit = () => {
    let auth = atob(
      JSON.parse(atob(window.localStorage.getItem("config"))).auth
    );
    let code = auth.split(":")[0];
    let dealerId = code.substring(0, code.lastIndexOf("-"));

    if (passcode === dealerId) {
      logout();
    } else {
      setErrorMessage("Invalid customer number.");
    }
  };

  const idleClickDisabled = window.isNative &&
    !(updateStatus && updateStatus.status === UPDATE_STATUS.STAGED);

  return (
    <Modal
      className={styles.modal}
      isOpen={isOpen}
      onRequestClose={onRequestClose}
    >
      {isNoticeOpen && (
        <div className={styles.disclaimer}>
          <h1>Third Party Notice</h1>
          <p style={{ paddingRight: "0.5em" }}>{thirdPartyNotice.text}</p>
        </div>
      )}

      {!isNoticeOpen && (
        <div className={styles.content}>
          <h1 className={styles.header}>
            <b>Catalog Information</b> - {configData.dealerName}
          </h1>

          {!window.isNative && (
            <KioskCard
              inverted={true}
              kiosk={{
                number: configData.number,
                location: configData.location,
                info: configData.info
              }}
            />
          )}

          <div className={styles.info}>{updateStatus.details}</div>

          <div className={styles.info}>
            {catalog.length} products are loaded.
          </div>

          {lastUpdatedAt && (
            <div className={styles.info}>Last checked: {lastUpdatedAt}</div>
          )}

          <Button 
            inverted 
            disabled={idleClickDisabled}
            className={styles.button} 
            onClick={(e) => !idleClickDisabled && onIdleClick(e)}
          >
            {window.isNative ? "Apply Catalog Updates" : "Set Idle"}
          </Button>

          <Button
            alt
            inverted
            className={styles.button}
            onClick={onDisclaimerClick}
          >
            Third Party Notice
          </Button>

          {!logoutPressed ? (
            <Button
              alt
              inverted
              className={styles.button}
              onClick={onLogoutClick}
            >
              Logout
            </Button>
          ) : (
            <Input
              className={styles.input}
              inverted
              buttonIcon={<MdExitToApp className={styles.icon} />}
              placeholder="Enter customer # to logout"
              value={passcode}
              onChange={handleCodeChange}
              onSubmit={handleCodeSubmit}
              type="password"
            />
          )}
          {errorMessage && <div>{errorMessage}</div>}

          <div className={styles.info} style={{ textAlign: "center" }}>
            <code>v{version}</code>
          </div>
        </div>
      )}
    </Modal>
  );
}
