import React, { useRef, useState, useEffect } from "react";
import { MdMailOutline, MdDone } from "react-icons/md";

import Button from "./button";
import Input from "./input";
import Loading from "./loading";
import { useOnClickOutside } from "../utils/hooks";
import { sendMail } from "../utils/service-api";
import { logEvent } from "../utils/logging";
import styles from "./email-button.module.css";

export default function EmailButton({
  inverted = false,
  className,
  style,
  subject,
  message,
  extraRecipients = [],
  getImageAttachments = null,
  keepActive = false,
  onSuccess,
  onError,
  loggingLabel,
  loggingValue
}) {
  let emailRef = useRef();
  useOnClickOutside(emailRef, () => !keepActive && setIsEmailActive(false));

  let [emailValue, setEmailValue] = useState("");
  const handleEmailChange = e => {
    setEmailValue(e.target.value.trim());
    onError("");
  };

  let [isEmailActive, setIsEmailActive] = useState(false);
  useEffect(() => {
    if (!isEmailActive) {
      setEmailValue("");
    } else {
      onError("");
    }
  }, [isEmailActive, onError]);

  useEffect(() => {
    if (keepActive && !isEmailActive) {
      setIsEmailActive(true);
    }
  }, [keepActive, isEmailActive]);

  let [emailSent, setEmailSent] = useState(null);
  useEffect(() => {
    if (emailSent) {
      const sentTimer = setTimeout(() => setEmailSent(null), 3000);
      return () => clearTimeout(sentTimer);
    }
  }, [emailSent]);

  const sendProductEmail = () => {
    setEmailSent(false);
    if (!keepActive) {
      setIsEmailActive(false);
    }
    let emailPattern = new RegExp(/^[^\s@]+@([^\s@.,]+\.)+[^\s@.,]{2,}$/);
    if (
      emailPattern.test(emailValue.trim()) ||
      (emailValue.trim() === "" && extraRecipients.length > 0)
    ) {
      let images = getImageAttachments !== null ? getImageAttachments() : null;
      let toAddr = emailValue;
      // include any extra email addresses here
      if (extraRecipients.length > 0) {
        if (toAddr) {
          toAddr = [toAddr, ...extraRecipients].join(";");
        } else {
          toAddr = extraRecipients.join(";");
        }
      }
      sendMail(toAddr, subject, message, images)
        .then(() => {
          setEmailSent(true);
          setEmailValue("");
          logEvent(
            "action",
            "email",
            loggingLabel,
            loggingValue,
            performance.now()
          );
          onSuccess();
        })
        .catch(() => {
          setEmailSent(null);
          onError("Unable to send email.");
        });
    } else {
      setEmailSent(null);
      onError("Invalid email address.");
    }
  };

  return (
    subject &&
    message && (
      <div
        ref={emailRef}
        className={`${styles.email} ${
          isEmailActive ? styles.active : ""
        } ${className}`}
        style={style}
      >
        {!isEmailActive ? (
          <Button
            inverted={inverted}
            style={{ minWidth: "10em" }}
            onClick={() => {
              emailSent === null && setIsEmailActive(true);
            }}
          >
            {emailSent === null ? (
              <>
                <MdMailOutline className={styles["left-icon"]} /> Email
              </>
            ) : emailSent === true ? (
              <>
                <MdDone className={styles["left-icon"]} /> Sent!
              </>
            ) : (
              <Loading color={"var(--color-text-inverted)"} />
            )}
          </Button>
        ) : (
          <Input
            borderless={inverted}
            icon={<MdMailOutline className={styles.icon} />}
            buttonIcon={
              emailSent === null ? (
                <>
                  <MdMailOutline className={styles["left-icon"]} /> Send
                </>
              ) : emailSent === true ? (
                <>
                  <MdDone className={styles["left-icon"]} /> Sent!
                </>
              ) : (
                <Loading color={"var(--color-text-inverted)"} />
              )
            }
            placeholder="hello@example.com"
            value={emailValue}
            onChange={handleEmailChange}
            onSubmit={sendProductEmail}
          />
        )}
      </div>
    )
  );
}
