import React from "react";
import { Transition } from "react-transition-group";

/**
 * Conditionally mounts or unmounts children when `in` is `true` or `false`.
 * Applies a fade-in on mount, and fade-out on unmount.
 */
export default function Fade({
  className = "",
  style = {},
  in: inProp,
  duration = 250,
  opacity = 1,
  children
}) {
  const defaultStyle = {
    transition: `opacity ${duration}ms ease-in-out`,
    opacity: 0
  };

  const transitionStyles = {
    entering: { opacity: opacity },
    entered: { opacity: opacity },
    exiting: { opacity: 0 },
    exited: { opacity: 0 }
  };

  return (
    <Transition
      in={inProp}
      timeout={duration}
      // access offsetHeight to trigger a reflow, see
      // https://github.com/reactjs/react-transition-group/issues/223
      onEnter={node => node.offsetHeight}
      mountOnEnter
      unmountOnExit
    >
      {state => (
        <div
          className={className}
          style={{
            ...style,
            ...defaultStyle,
            ...transitionStyles[state]
          }}
        >
          {children}
        </div>
      )}
    </Transition>
  );
}
