import React, { useState, useRef } from "react";
import { MdKeyboardArrowUp, MdKeyboardArrowDown } from "react-icons/md";

import Button from "./button";
import { useOnClickOutside } from "../utils/hooks";

import styles from "./dropdown.module.css";

export default function Dropdown({
  alt = true,
  inverted = false,
  triggerClass = "",
  triggerStyle = {},
  itemClass = "",
  itemStyle = {},
  defaultItemLabel = "",
  showDefault = true,
  items = [
    { label: "Item 1", value: "item1" },
    { label: "Item 2", value: "item2" },
    {
      label: "Item 3 Item 3 Item 3 Item 3 Item 3 Item 3 Item 3 ",
      value: "item3"
    }
  ],
  selectedItem = null,
  onChange = selectedItem => {}
}) {
  let [isActive, setIsActive] = useState(false);
  let dropdownRef = useRef();
  useOnClickOutside(dropdownRef, () => setIsActive(false));

  const isSelected = item => {
    return selectedItem !== null && selectedItem.value === item.value;
  };

  const handleClick = item => {
    setIsActive(false);
    onChange(item);
  };

  return (
    <div
      ref={dropdownRef}
      className={`${styles.dropdown} ${isActive ? styles["is-active"] : ""}`}
    >
      <Button
        alt={alt}
        inverted={inverted}
        className={`${styles.trigger} ${triggerClass}`}
        style={triggerStyle}
        onClick={() => setIsActive(!isActive)}
      >
        <span className={styles.item} style={{ padding: 0 }}>
          {selectedItem !== null ? selectedItem.label : defaultItemLabel}
        </span>

        {isActive ? (
          <MdKeyboardArrowUp className={styles.icon} />
        ) : (
          <MdKeyboardArrowDown className={styles.icon} />
        )}
      </Button>

      <div className={styles.content}>
        {defaultItemLabel && showDefault && (
          <div
            className={`
              ${styles.item}
              ${selectedItem === null ? styles.selected : ""}
              ${itemClass}
            `}
            style={itemStyle}
            onClick={() => handleClick(null)}
          >
            {defaultItemLabel}
          </div>
        )}

        {items.map((item, i) => (
          <div
            key={i}
            className={`
              ${styles.item}
              ${isSelected(item) ? styles.selected : ""}
              ${itemClass}
            `}
            style={itemStyle}
            onClick={() => handleClick(item)}
          >
            {item.label}
          </div>
        ))}
      </div>
    </div>
  );
}
