import React from "react";

import Screensaver from "./components/screensaver";
import NoCatalog from "./components/no-catalog";
import CollectionFilterPicker from "./components/collection-filter-picker";
import CatalogFilterMini from "./components/catalog-filter-mini";
import VisualizerButton from "./native/visualizer-button";

import Grid from "./components/grid";
import ProductDetails from "./components/product-details";
import ProductScene from "./components/product-scene";
import ProductList from "./components/product-list";
import styles from "./app.module.css";

export default function App() {
  return (
    <div className={styles.app}>
      <Screensaver />
      <NoCatalog />
      <CollectionFilterPicker />
      <CatalogFilterMini />
      <VisualizerButton />
      <Grid
        left={<ProductDetails />}
        middle={<ProductScene />}
        right={<ProductList />}
      />
    </div>
  );
}
