import React from "react";
import { CSSTransition } from "react-transition-group";
import styles from "./product-list.module.css";

import { useUpdateStatus } from "../state/update-status";
import { logEvent } from "../utils/logging";

export default function ProductRow({
  style,
  product,
  selected = false,
  onProductSelected,
  visibleIndex
}) {
  const image = product.variants[0].image;
  // Need to refresh the image if it changed from a catalog update
  // include `lastUpdatedAt` in the src
  let { lastUpdatedAt } = useUpdateStatus();

  // Animate to draw attention after the image loads.
  const animationDelayMs = visibleIndex >= 0 ? 100 * (visibleIndex + 1) : 0;
  const imgStyle = { animationDelay: `${animationDelayMs}ms` };

  const handleProductClick = e => {
    onProductSelected(product);
    logEvent(
      "click",
      "button",
      "product list item",
      product.handle,
      e.timeStamp,
      e.clientX,
      e.clientY
    );
  };

  return (
    product && (
      <div className={styles.row} style={style}>
        <img
          key={product.handle}
          style={imgStyle}
          className={`${styles.image} ${styles.appear}`}
          alt={image.altText || "no description"}
          src={`${image.path}?${lastUpdatedAt}`}
          onClick={handleProductClick}
        />

        <CSSTransition
          in={selected}
          classNames={{
            enterActive: styles["tab-enter-active"],
            enterDone: styles["tab-enter-done"],
            exitActive: styles["tab-exit-active"]
          }}
          timeout={250}
          appear
          mountOnEnter
          unmountOnExit
        >
          <div className={styles.tab} />
        </CSSTransition>
      </div>
    )
  );
}
