import React, { useEffect, useState, useCallback } from "react";

import { useKeyboard } from "../state/keyboard";

import Button from "./button";
import styles from "./input.module.css";
import { MdCancel } from "react-icons/md";

export default function Input({
  className = "",
  style = {},
  inverted = false,
  borderless = false,
  icon = null,
  buttonIcon = null,
  placeholder = "",
  clearEnabled = false,
  value = "",
  onChange = () => {},
  onSubmit = null,
  onClear = null,
  type = "",
  shouldFocusOnRender = false
}) {
  const [input, setInput] = useState(null);
  const setInputRef = useCallback(node => {
    if (node != null) setInput(node);
  }, []);

  const handleFormSubmit = e => {
    e.preventDefault();
    if (onSubmit !== null) {
      onSubmit();
    }
  };

  const isDesktop = !window.isNative;
  const {
    setIsActive: setIsKbActive,
    setInputField: setKbInput,
    setInputValue: setKbValue,
    setOnChangeCallback,
    setOnSubmitCallback
  } = useKeyboard();

  useEffect(() => {
    if (isDesktop) {
      return () => setIsKbActive(false);
    }
  }, [isDesktop, setIsKbActive]);

  useEffect(() => {
    if (isDesktop && onChange && onSubmit) {
      const cb = v => {
        // The simple-keyboard will return a string,
        // format this into a fake event for compatibility.
        onChange({ target: { value: v } });
      };
      setOnChangeCallback(() => cb);
      setOnSubmitCallback(() => onSubmit);
    }
  }, [isDesktop, setOnChangeCallback, onChange, setOnSubmitCallback, onSubmit]);

  useEffect(() => {
    if (isDesktop) {
      setKbValue(value);
    }
  }, [isDesktop, setKbValue, value]);

  const initKeyboard = () => {
    if (isDesktop) {
      setIsKbActive(true);
      setKbInput(input);
      setKbValue(value);
      const cb = v => {
        // The simple-keyboard will return a string,
        // format this into a fake event for compatibility.
        onChange({ target: { value: v } });
      };
      setOnChangeCallback(() => cb);
      setOnSubmitCallback(() => onSubmit);
    }
  };

  return (
    <div
      className={`
        ${styles.input} 
        ${inverted ? styles.inverted : ""} 
        ${borderless ? styles.borderless : ""}
        ${className} 
      `}
      style={style}
    >
      <form onSubmit={handleFormSubmit}>
        {icon !== null && <div style={{ display: "flex" }}>{icon}</div>}
        <input
          style={{ width: "100%" }}
          ref={setInputRef}
          placeholder={placeholder}
          value={value}
          onChange={onChange}
          type={type}
          autoFocus={shouldFocusOnRender}
          onClick={() => initKeyboard()}
          onFocus={() => initKeyboard()}
        />
        {clearEnabled && onClear !== null && value && (
          <div className={styles.clear} onClick={onClear}>
            <MdCancel style={{ width: "1.6em", height: "1.6em" }} />
          </div>
        )}
        {buttonIcon !== null && (
          <Button
            inverted={borderless ? !inverted : inverted}
            onClick={onSubmit}
            style={{ boxShadow: "none" }}
          >
            {buttonIcon}
          </Button>
        )}
      </form>
    </div>
  );
}
