import React, { useState, useEffect } from "react";

import Button from "./button";
import Expandable from "./expandable";
import BuyButton from "./buy-button";
import InfoButton from "./info-button";
import ConfigModal from "./config-modal";
import { useConfiguration } from "../state/configuration";
import { useSelectedProduct } from "../state/selected-product";
import { compareVariantSizes } from "../utils/compare";
import availableQuantityText from "../utils/availableQuantityText";
import styles from "./product-details.module.css";

export default function ProductDetails() {
  let { configData, isIdle } = useConfiguration();
  let {
    selectedProduct,
    selectedVariant,
    setSelectedVariant
  } = useSelectedProduct();
  let [variants, setVariants] = useState([]);

  useEffect(() => {
    if (selectedProduct && selectedProduct.variants.length > 0) {
      // sort variants
      let sortedVariants = selectedProduct.variants
        .slice()
        .sort(compareVariantSizes);
      // prune duplicate variant sizes and only show one per size
      // this should only be a problem with custom rugs
      let uniqueSizes = new Set();
      let prunedVariants = [];
      for (const v of sortedVariants) {
        if (!uniqueSizes.has(v.size)) {
          prunedVariants.push(v);
          uniqueSizes.add(v.size);
        }
      }
      setVariants(prunedVariants);
    }
  }, [selectedProduct]);

  useEffect(() => {
    if (!variants || !selectedVariant) return;

    // If custom rugs is enabled, an invisible variant may be selected
    // due to having multiple variants per size.
    // Select the last rendered variant, if this happens.
    const skus = variants.map(v => v.sku);
    if (!skus.includes(selectedVariant.sku)) {
      setSelectedVariant(variants[variants.length - 1]);
    }
  }, [variants, selectedVariant, setSelectedVariant]);

  let { productSpecs, ataglanceIcons } = useCustomTags(
    selectedProduct,
    configData.customTags
  );

  const isVariantSelected = variant => variant.id === selectedVariant.id;
  const formatSize = size => size.replace("x", " ⨯ ");

  let [isConfigOpen, setIsConfigOpen] = useState(false);

  let [lastClick, setLastClick] = useState({ count: 0, ts: null });
  const handleTitleClick = e => {
    if (window.isNative) return;

    // Counting clicks the hard way, since e.detail
    // bugs out on Windows touchscreen events for some reason.
    let { count, ts } = lastClick;
    if (ts === null || e.timeStamp - ts < 500) {
      count++;
    } else {
      count = 1;
    }
    if (count === 5) {
      count = 1;
      setIsConfigOpen(true);
    }
    setLastClick({ count, ts: e.timeStamp });
  };

  const buyEnabled = configData.buyEnabled && selectedProduct?.onlineStoreUrl;
  const availableQuantityEnabled = configData?.availableQuantityEnabled;

  const customRugsCollection = configData.collectionFilters.find(
    c => c.customRugs
  );
  const customRugsEnabled =
    customRugsCollection &&
    selectedProduct?.collections.includes(customRugsCollection.value);

  return (
    <>
      <ConfigModal
        isOpen={isConfigOpen}
        onRequestClose={() => setIsConfigOpen(false)}
      />

      {selectedProduct && (
        <div className={styles.details}>
          <h1 className={styles.title} onClick={handleTitleClick}>
            {selectedProduct.title}
          </h1>

          <div className={styles.sizes}>
            {variants.map((variant, i) => (
              <Button
                key={i}
                alt={!isVariantSelected(variant)}
                className={styles.size}
                onClick={() => setSelectedVariant(variant, true)}
                loggingLabel={"variant size"}
                loggingValue={{
                  product: selectedProduct.handle,
                  variant: variant.size
                }}
              >
                {formatSize(variant.size)}
              </Button>
            ))}
          </div>

          <div className={styles["button-wrapper"]}>
            {buyEnabled ? (
              <BuyButton product={selectedProduct} variant={selectedVariant} />
            ) : (
              <InfoButton
                product={selectedProduct}
                variant={selectedVariant}
                customRugsEnabled={customRugsEnabled}
              />
            )}
          </div>

          <div className={styles["button-subtext"]}>
            {availableQuantityEnabled && (
              <i>
                {availableQuantityText(
                  selectedVariant,
                  availableQuantityEnabled
                )}
              </i>
            )}
          </div>

          <Expandable
            // needs a key to update, in case the description is the same across products
            key={selectedProduct.handle + isIdle}
            className={styles.description}
            minHeight={"12em"}
            maxHeight={!window.isNative ? "40em" : "100%"}
          >
            <div style={{ margin: "0 1em" }}>{selectedProduct.description}</div>
          </Expandable>

          {ataglanceIcons.length > 0 && (
            <div className={styles["ataglance-wrapper"]}>
              {ataglanceIcons.map((icon, i) => (
                <div key={i} className={styles.ataglance}>
                  <img
                    key={i}
                    className={styles["ataglance-icon"]}
                    alt={`ataglance${i}`}
                    src={icon.path}
                  />
                  <span className={styles["ataglance-label"]}>
                    {icon.value}
                  </span>
                </div>
              ))}
            </div>
          )}

          {productSpecs.length > 0 && (
            <div className={styles["product-specs"]}>
              {productSpecs.map((spec, i) => {
                return (
                  spec.label &&
                  spec.value && (
                    <React.Fragment key={i}>
                      <div className={styles["spec-label"]}>{spec.label}</div>
                      <div className={styles["spec-value"]}>{spec.value}</div>
                    </React.Fragment>
                  )
                );
              })}
            </div>
          )}
        </div>
      )}
    </>
  );
}

function useCustomTags(selectedProduct, customTags) {
  let [productSpecs, setProductSpecs] = useState([]);
  let [ataglanceIcons, setAtaglanceIcons] = useState([]);

  useEffect(() => {
    if (selectedProduct === null) {
      return;
    }

    let _productSpecs = [];
    let _ataglanceIcons = [];

    selectedProduct.tags.forEach(tag => {
      let [prefix, value] = tag.split("_", 2);
      if (!prefix || !value) {
        return;
      }

      let customTag = customTags.find(ctag => ctag.prefix === prefix);
      if (!customTag) {
        return;
      }

      if (customTag.label) {
        _productSpecs.push({ label: customTag.label, value: value });
      }
      if (customTag.icons && customTag.icons.length > 0) {
        let icon = customTag.icons.find(icon => icon.value === value);
        if (icon) {
          _ataglanceIcons.push(icon);
        }
      }
    });

    setProductSpecs(_productSpecs);
    setAtaglanceIcons(_ataglanceIcons);
  }, [selectedProduct, customTags]);

  return { productSpecs, ataglanceIcons };
}
